(window.TRENER_PACKS=window.TRENER_PACKS||{})["zadanie-3-valentnost-so"]={"id": "zadanie-3-valentnost-so", "subject": "Химия", "title": "Задание 3 · Валентность, ЭО и степень окисления", "version": "26.11.2026", "konspekt": "zadanie-3-valentnost-so", "codes": ["1.3"], "kod": {"p": [{"id": "p1", "t": "Электроотрицательность и смещение электронной пары", "x": "Электроотрицательность (ЭО) — способность атома в соединении притягивать общие электронные пары; в таблице ФИПИ она растёт вправо по периоду и вверх по главной подгруппе — к фтору F (3,98). Атом с большей ЭО получает отрицательную степень окисления, с меньшей — положительную; благородные газы (He, Ne, Ar) в ряд ЭО не включают.", "ref": "01.1"}, {"id": "p2", "t": "Степень окисления, стандарт записи ФИПИ и электронейтральность", "x": "Степень окисления (с.о.) — условный заряд атома при допущении полной ионности всех полярных связей. В стандарте ФИПИ степень окисления пишут знаком вперёд (Fe^{+3}, O^{−2}), а заряд иона — цифрой вперёд (Fe^{3+}, SO4^{2−}). Сумма с.о. всех атомов в нейтральной молекуле равна 0, а в сложном ионе — его заряду.", "ref": "02.1"}, {"id": "p3", "t": "Диапазон [НСО; ВСО] и алгебраическая разность Δ", "x": "Для большинства элементов высшая с.о. (ВСО) равна +N (номеру группы), низшая с.о. неметаллов равна N − 8, а для всех металлов и бора в модели ЕГЭ низшая с.о. равна 0. Разность всегда считают алгебраически: Δ = ВСО − НСО, поэтому все стандартные неметаллы дают ровно 8, кислород — 4, фтор — 1, водород — 2, а любой металл — свою ВСО.", "ref": "03.1"}, {"id": "p4", "t": "Валентность, механизмы связи и потолок 2-го периода", "x": "Валентность — число ковалентных связей атома, записывается римскими цифрами (I–VII) без знака и складывается из обменных и донорно-акцепторных связей. На 2-м уровне нет 2d-орбиталей (всего 4 орбитали: 2s и три 2p), поэтому элементы 2-го периода не могут образовать больше четырёх связей: потолок N = IV, O = III, F = I.", "ref": "04.1"}, {"id": "p5", "t": "Четыре причины расхождения валентности и |с.о.|", "x": "Валентность считает число чёрточек-связей, а степень окисления — итоговый сдвиг электронов со знаком. Они расходятся в четырёх случаях: простые вещества (N2: III и 0), неполярные связи Э—Э в сложных веществах (H2O2, FeS2, C2H6), донорно-акцепторные связи (CO, HNO3, NH4^{+}, H3O^{+}) и связи с атомами разной ЭО (CH3OH, HCHO, HCOOH).", "ref": "05.1"}, {"id": "p6", "t": "d-элементы и три списка исключений задания № 3", "x": "У d-элементов 4-го периода в связях участвуют 4s- и 3d-электроны: от Sc (+3) до Mn (+7) ВСО совпадает с номером группы, но у Fe максимум +6 (≠ VIII), а у Cu — +2 (≠ I). Важно строго разводить три списка: ВСО ≠ номеру группы (F, O, Fe, Cu), высшая валентность ≠ номеру группы (N, O, F, Fe, Cu) и постоянная с.о. в соединениях (F, Li–Cs, Be–Ba, Al, Zn, Ag, Sc).", "ref": "06.1"}, {"id": "p7", "t": "Двухшаговый фильтр для оксоанионов ЭOₓ^{n−}, оксидов и ЛВС", "x": "Для общих формул ЭOₓ^{n−}, ЭₓOᵧ и ЭHₙ нельзя ограничиваться алгеброй: сначала находят требуемую степень окисления (например, s = 2x − n для ЭOₓ^{n−}), а затем проверяют реальное существование иона или соединения в курсе ЕГЭ. Летучие водородные соединения (ЛВС) образуют только неметаллы IVA–VIIA групп, но не металлы.", "ref": "07.1"}, {"id": "p8", "t": "Четырёхшаговый алгоритм задания № 3 КИМ ЕГЭ-2027", "x": "Задание № 3 даёт 1 балл, в ответе всегда ровно две цифры, и порядок цифр значения не имеет. Надёжный алгоритм: 1) выделить слово-переключатель (валентность vs с.о., «в соединениях», «не равна», оксоанион); 2) выписать паспорт [НСО; ВСО] для всех 5 элементов; 3) отобрать 2 подходящих; 4) убедиться, что остальные 3 точно не подходят.", "ref": "08.1"}], "z": [{"id": "z1", "x": "Рабочий ряд ЭО неметаллов: F (3,98) > O (3,44) > Cl (3,16) > N (3,04) > Br > I > S (2,58) > C (2,55) > H (2,20) ≈ P (2,19) > B (2,04) > Si (1,90) > металлы.", "sk": "eo_shift", "ref": "01.15"}, {"id": "z2", "x": "В силане SiH4 строго Si^{+4} и H^{−1} (так как ЭО(H) = 2,20 > ЭО(Si) = 1,90), а в фосфине PH3 по школьной традиции ЕГЭ принимают P^{−3} и H^{+1}.", "sk": "eo_shift", "ref": "01.18"}, {"id": "z3", "x": "Запись в стандарте ФИПИ: степень окисления — сначала знак (Fe^{+3}, Cr^{+6}, O^{−2}, для № 29), заряд иона — сначала цифра (Fe^{3+}, SO4^{2−}, Cr2O7^{2−}, для № 30).", "sk": "so_calc", "ref": "02.6"}, {"id": "z4", "x": "Три «хитрых» вещества ЕГЭ: в пирите FeS2 железо +2, сера −1 (связь —S—S—); в окалине Fe3O4 одновременно Fe^{+2} и Fe^{+3}; в NH4NO3 два азота считают раздельно (−3 и +5).", "sk": "so_calc", "ref": "02.15"}, {"id": "z5", "x": "Ровно 4 элемента ЕГЭ имеют равные по модулю высшую и низшую с.о. (|ВСО| = |НСО|): C (+4/−4), Si (+4/−4), O (+2/−2) и H (+1/−1).", "sk": "delta_range", "ref": "03.15"}, {"id": "z6", "x": "У всех металлов (включая d-элементы) и у бора B в школьной модели ЕГЭ низшая с.о. равна 0 (формула N − 8 к ним не применяется!), поэтому Δ(металла) = ВСО.", "sk": "delta_range", "ref": "03.16"}, {"id": "z7", "x": "У азота N высшая валентность строго IV (в NH4^{+}, HNO3, N2O5 — нет 2d-орбиталей), но высшая степень окисления равна +5 (совпадает с номером группы V!).", "sk": "val_period2", "ref": "04.13"}, {"id": "z8", "x": "У кислорода O высшая валентность равна III (в H3O^{+} и CO за счёт донорно-акцепторной связи; по обменному механизму II), а у фтора F всегда только I.", "sk": "val_period2", "ref": "04.12"}, {"id": "z9", "x": "В угарном газе CO тройная связь (2 обменные + 1 донорно-акцепторная O → C): валентность и C, и O равна III, но степени окисления равны C^{+2} и O^{−2}.", "sk": "val_vs_so", "ref": "05.7"}, {"id": "z10", "x": "Степень окисления 0 бывает и в сложных веществах: у углерода в формальдегиде HCHO, глюкозе C6H12O6 и дихлорметане CH2Cl2 (при валентности IV).", "sk": "val_vs_so", "ref": "05.8"}, {"id": "z11", "x": "У водорода H постоянная валентность I, но ПЕРЕМЕННАЯ степень окисления (+1 в H2O/HCl и −1 в NaH/SiH4); у Zn (+2), Al (+3), Ag (+1), F (−1), IA (+1), IIA (+2) — постоянная с.о. в соединениях.", "sk": "d_exceptions", "ref": "06.14"}, {"id": "z12", "x": "В школьной модели ЕГЭ: ВСО(Fe) = +6 (в ферратах K2FeO4, но оксида FeO3 нет!), ВСО(Cu) = +2 (CuO, CuSO4), ВСО(Ag) = +1 (постоянная).", "sk": "d_exceptions", "ref": "06.7"}, {"id": "z13", "x": "Оксоанионы ЕГЭ с общими формулами: ЭO4^{2−} (+6: SO4^{2−}, CrO4^{2−}, MnO4^{2−}, FeO4^{2−}); ЭO4^{−} (+7: MnO4^{−}, ClO4^{−}); ЭO3^{−} (+5: NO3^{−}, ClO3^{−}, PO3^{−}); ЭO4^{3−} (+5: PO4^{3−}, но НЕ NO4^{3−}!).", "sk": "oxo_hydrides", "ref": "07.6"}, {"id": "z14", "x": "Фтор F не образует оксидов (OF2 — фторид кислорода O^{+2}, F^{−1}); активные металлы (NaH, CaH2) образуют солеобразные гидриды, а не летучие водородные соединения.", "sk": "oxo_hydrides", "ref": "07.9"}]}, "skills": [{"id": "eo_shift", "name": "Электроотрицательность и направление сдвига электронов", "ref": "01", "idea": "Определять по таблице ФИПИ и рабочему ряду ЭО неметаллов, к какому атому смещается электронная пара в любой связи (включая OF2, SiH4, NaH, B2H6, PH3).", "pre": {"type": "one", "q": "Почему в соединении OF2 у кислорода степень окисления равна +2, а не −2, как в большинстве других веществ?", "o": ["Фтор обладает наибольшей электроотрицательностью среди всех элементов (3,98 > 3,44), поэтому перетягивает общие электронные пары от кислорода на себя", "Кислород в OF2 проявляет металлические свойства", "Фтор стоит в 3-м периоде и имеет больше электронных слоёв, чем кислород", "В молекуле OF2 связь неполярная, поэтому знаки расставляют произвольно"], "a": 0, "ex": "Фтор (3,98) — единственный элемент таблицы, превосходящий кислород (3,44) по электроотрицательности. Поэтому обе пары в связях O—F смещены к фтору: O^{+2} и F^{−1}.", "d": {"1": "Кислород — типичный неметалл, второй по ЭО после фтора.", "2": "И кислород, и фтор стоят во 2-м периоде; у фтора больше заряд ядра (+9 против +8) при тех же двух слоях.", "3": "Связи O—F ковалентные полярные, смещённые строго к более электроотрицательному фтору."}}, "pair": {"type": "one", "cases": [["Метан CH4", "ЭО(C) = 2,55 > ЭО(H) = 2,20 → электроны смещены к углероду: C^{−4}H4^{+1}"], ["Силан SiH4", "ЭО(H) = 2,20 > ЭО(Si) = 1,90 → электроны смещены к водороду: Si^{+4}H4^{−1}"]], "q": "Почему в двух водородных соединениях элементов одной IVA-подгруппы (CH4 и SiH4) водород имеет противоположные степени окисления?", "o": ["Водород (2,20) стоит по ЭО между кремнием (1,90) и углеродом (2,55): у C он отдаёт электроны (+1), а у Si — притягивает к себе (−1)", "Кремний — металл, а углерод — неметалл", "Силан имеет ионную связь, как NaH", "В силане кремний не может проявлять отрицательную степень окисления ни в каких веществах"], "a": 0, "ex": "Сверху вниз по IVA-подгруппе ЭО падает от C (2,55) к Si (1,90), пересекая значение водорода (2,20). Поэтому в CH4 — C^{−4}, H^{+1}, а в SiH4 — Si^{+4}, H^{−1}."}, "fade": {"q": "Восстанови ключевые правила электроотрицательности и рабочего ряда неметаллов:", "steps": ["По таблице ФИПИ электроотрицательность растёт слева направо по периоду и снизу вверх по главной подгруппе — к {фтору F|неону Ne|хлору Cl}, а благородные газы в ряд ЭО {не включают|ставят выше фтора}.", "Второе место по ЭО занимает {кислород O|хлор Cl|азот N}, поэтому положительную с.о. кислород проявляет только в соединениях с {фтором|хлором|серой}.", "В силане SiH4 у кремния степень окисления {+4|−4}, а у водорода {−1|+1}; в фосфине PH3 по школьной традиции ЕГЭ принимают {P^{−3} и H^{+1}|P^{+3} и H^{−1}}."]}, "bug": {"q": "Найди ошибочный шаг в определении степеней окисления в четырёх бинарных соединениях: OF2, SiH4, NaH, CH4:", "steps": ["В NaH натрий — щелочной металл (ЭО = 0,93), водород — неметалл (2,20), поэтому Na^{+1} и H^{−1}.", "В CH4 углерод (2,55) электроотрицательнее водорода (2,20), поэтому C^{−4} и H^{+1}.", "В OF2 кислород всегда имеет степень окисления −2, а два атома фтора уравновешивают его, получая по +1.", "В SiH4 водород (2,20) электроотрицательнее кремния (1,90), поэтому Si^{+4} и H^{−1}."], "bad": 2, "fix": "Фтор (3,98) электроотрицательнее кислорода (3,44) и никогда не бывает положительным: в OF2 строго O^{+2} и F^{−1} (фторид кислорода).", "why": "Приписывание фтору положительной с.о. — грубый антипаттерн: у фтора максимальная ЭО в таблице, в любых соединениях он строго −1."}, "recall": {"q": "Назови по памяти 4 главных ориентира по электроотрицательности для задания № 3.", "points": ["ЭО растёт вправо и вверх к F (3,98); благородные газы (He, Ne, Ar) не включают в ряд ЭО.", "F в соединениях всегда −1 (никогда не бывает положительным); O положителен только со фтором (OF2: O^{+2}, O2F2: O^{+1}).", "Водород (2,20) электроотрицательнее всех металлов, Si (1,90) и B (2,04) → в NaH, CaH2, SiH4, B2H6 у водорода −1.", "В CH4 (C 2,55) у водорода +1; в PH3 по школьной традиции ЕГЭ принимают P^{−3} и H^{+1}."]}}, {"id": "so_calc", "name": "Степень окисления: запись ФИПИ и расчёт в любых формулах", "ref": "02", "idea": "Строго различать запись степени окисления и заряда иона и безошибочно рассчитывать с.о. в молекулах, ионах, пероксидах, пирите FeS2, Fe3O4 и NH4NO3.", "pre": {"type": "one", "q": "Какая пара записей ПОЛНОСТЬЮ соответствует стандарту ФИПИ для электронного баланса (№ 29) и ионного уравнения (№ 30)?", "o": ["Степень окисления: Fe^{+3}, Cr^{+6}; заряд иона: Fe^{3+}, SO4^{2−}", "Степень окисления: Fe^{3+}, Cr^{6+}; заряд иона: Fe^{+3}, SO4^{-2}", "Степень окисления: Fe^{3+}, SO4^{2−}; заряд иона: Fe^{+3}, Cr^{+6}", "В критериях ФИПИ порядок знака и цифры не имеет значения"], "a": 0, "ex": "Жёсткое правило ФИПИ: степень окисления — сначала знак, затем цифра (Fe^{+3}, Cr^{+6}, O^{−2}); заряд иона — сначала цифра, затем знак (Fe^{3+}, SO4^{2−}, Cr2O7^{2−}).", "d": {"1": "Здесь форматы перепутаны местами: запись SO4^{-2} в № 30 обнуляет балл за ионное уравнение.", "2": "SO4^{2−} — сложный ион с реальным зарядом 2−, а не степень окисления атома.", "3": "В № 30 за неправильную запись заряда иона (знак перед цифрой) снимают балл."}}, "pair": {"type": "one", "cases": [["Сульфид железа(II) FeS", "Обычный сульфид-ион S^{2−}: у железа +2, у серы −2"], ["Пирит (дисульфид железа) FeS2", "Катион Fe^{2+} и персульфид-ион S2^{2−} со связью —S—S—: у железа +2, у серы −1"]], "q": "Почему в пирите FeS2 степень окисления железа равна +2, а серы −1 (а не Fe^{+4} и S^{−2})?", "o": ["Пирит содержит ион Fe^{2+} и анион S2^{2−} с ковалентной неполярной связью —S—S—, поэтому каждый атом серы имеет с.о. −1 (+2 + 2·(−1) = 0)", "Железо вообще не может иметь степень окисления выше +2", "Сера никогда не проявляет степень окисления −2 в соединениях с металлами", "В пирите электронейтральность не соблюдается"], "a": 0, "ex": "В пирите FeS2 (как и в пероксиде H2O2) два атома халькогена связаны между собой (—S—S—), поэтому на каждый атом S приходится заряд −1, а на Fe — +2."}, "fade": {"q": "Восстанови шаги алгебраического расчёта степеней окисления в дихромат-ионе Cr2O7^{2−} и нитрате аммония NH4NO3:", "steps": ["В сложном ионе Cr2O7^{2−} сумма степеней окисления всех атомов равна {−2|0|+2}, поэтому составляем уравнение 2·x + 7·(−2) = −2, откуда x = {+6|+7|+3}.", "В пероксиде натрия Na2O2 сначала фиксируем постоянную с.о. {натрия (+1)|кислорода (−2)}, откуда для кислорода получаем {−1|−2|+1}.", "В нитрате аммония NH4NO3 два атома азота находятся в разных ионах ({NH4^{+} и NO3^{−}|NH3 и NO2}), поэтому их степени окисления считают раздельно: {−3 и +5|+1 и +1|−3 и +3}."]}, "bug": {"q": "Найди ошибочный шаг в определении степени окисления азота в нитрате аммония NH4NO3:", "steps": ["Записываем брутто-формулу соли: N2H4O3.", "Принимаем постоянные опорные значения: H = +1, O = −2.", "Считаем одинаковую степень окисления для обоих атомов азота: 2x + 4·(+1) + 3·(−2) = 0 → 2x = +2 → x = +1, значит оба атома азота имеют с.о. +1.", "Для проверки солей с двумя разными ионами одного элемента нужно разложить вещество на катион и анион."], "bad": 2, "fix": "Усреднять атомы азота в NH4NO3 нельзя! В катионе NH4^{+} азот имеет с.о. −3 (x + 4 = +1), а в анионе NO3^{−} — с.о. +5 (x − 6 = −1).", "why": "В солях аммония с азотсодержащими кислотными остатками (NH4NO3, NH4NO2) атомы азота химически неравноценны и имеют разные с.о."}, "recall": {"q": "Назови по памяти 4 опорных правила расчёта степени окисления и 3 «хитрых» вещества ЕГЭ.", "points": ["Постоянные с.о. в соединениях: F (−1), IA (+1), IIA и Zn (+2), Al (+3), Ag (+1); в простых веществах всегда 0.", "В молекуле сумма с.о. с учётом индексов равна 0, в сложном ионе — заряду иона с его знаком.", "H обычно +1 (−1 в гидридах металлов, B2H6, SiH4); O обычно −2 (−1 в пероксидах, −1/2 в KO2, +2 в OF2, +1 в O2F2).", "Хитрые вещества: FeS2 (Fe^{+2}, S^{−1}), Fe3O4 (один Fe^{+2} и два Fe^{+3}), NH4NO3 (N^{−3} и N^{+5}), Na2S2O3 (средняя S^{+2})."]}}, {"id": "delta_range", "name": "Высшая, низшая степень окисления и разность Δ", "ref": "03", "idea": "Мгновенно находить диапазон [НСО; ВСО], алгебраическую разность Δ = ВСО − НСО и список элементов с |ВСО| = |НСО| для металлов, неметаллов и всех исключений.", "pre": {"type": "one", "q": "Чему равна разность между высшей и низшей степенями окисления (Δ = ВСО − НСО) у серы S (VIA группа)?", "o": ["8, так как +6 − (−2) = +6 + 2 = 8", "4, так как 6 − 2 = 4", "6, так как низшая степень окисления равна 0", "−8, так как −2 − 6 = −8"], "a": 0, "ex": "У серы ВСО = +6, НСО = 6 − 8 = −2. Разность Δ = ВСО − НСО = +6 − (−2) = 8 (как у всех стандартных неметаллов C, Si, N, P, S, Cl, Br, I).", "d": {"1": "Классическая ошибка: потеря знака минуса при вычитании отрицательной НСО (вычли |НСО| вместо НСО).", "2": "НСО = 0 бывает у металлов и бора, но сера — неметалл VIA группы с НСО = −2 (например, H2S).", "3": "Разность между высшей и низшей с.о. — это (высшая − низшая), всегда неотрицательная длина отрезка."}}, "pair": {"type": "one", "cases": [["Фтор F (VIIA) и натрий Na (IA)", "F: [−1; 0] → Δ = 0 − (−1) = 1;  Na: [0; +1] → Δ = +1 − 0 = 1"], ["Водород H и магний Mg (IIA)", "H: [−1; +1] → Δ = +1 − (−1) = 2;  Mg: [0; +2] → Δ = +2 − 0 = 2"]], "q": "Какая пара из неметалла и металла имеет ОДИНАКОВУЮ разность Δ = 3 между высшей и низшей степенями окисления в школьной модели ЕГЭ?", "o": ["Бор B [0; +3] и алюминий Al [0; +3]", "Кислород O [−2; +2] и алюминий Al [0; +3]", "Азот N [−3; +5] и хром Cr [0; +6]", "Фтор F [−1; 0] и скандий Sc [0; +3]"], "a": 0, "ex": "В школьной модели ЕГЭ для бора (как и для металлов) НСО = 0, ВСО = +3 → Δ(B) = 3, ровно столько же у Al (+3 − 0 = 3) и Sc (+3 − 0 = 3)."}, "fade": {"q": "Заполни ключевые формулы и исключения для расчёта НСО, ВСО и разности Δ:", "steps": ["Для стандартных неметаллов (C, Si, N, P, S, Cl, Br, I) разность Δ = ВСО − НСО всегда равна {8|4|6}, потому что (+N) − (N − 8) = 8.", "Для всех металлов и для бора B (в модели ЕГЭ) низшая степень окисления равна {0|N − 8|−1}, поэтому для любого металла Δ совпадает с его {высшей с.о.|номером периода|зарядом ядра}.", "Условию |ВСО| = |НСО| в школьном курсе ЕГЭ отвечают ровно четыре элемента: {C, Si, O и H|C, Si, N и P|C, S, Cl и F}."]}, "bug": {"q": "Найди ошибочный шаг в решении задачи Демоверсии ЕГЭ-2027: из ряда 1) O  2) F  3) Al  4) Si  5) Li выбрать два элемента, которые в соединениях могут принимать как положительную, так и отрицательную с.о.:", "steps": ["Проверяем Al (3) и Li (5): это металлы, в соединениях они принимают только положительные с.о. (+3 и +1), поэтому не подходят.", "Проверяем F (2): самый электроотрицательный элемент, в соединениях всегда −1 (положительных не бывает) — не подходит.", "Проверяем O (1): кислород почти всегда −2, а положительной степени окисления у него не бывает, поэтому O не подходит.", "Проверяем Si (4): в SiO2 и SiH4 кремний имеет +4, а в силицидах (Mg2Si) — −4, значит Si подходит."], "bad": 2, "fix": "У кислорода ЕСТЬ положительная степень окисления: +2 в OF2 (и +1 в O2F2)! Поэтому подходят именно O (1) и Si (4) → ответ: 14.", "why": "Главная ловушка Демоверсии ЕГЭ-2027: забывают про фторид кислорода OF2, где кислород положителен (+2)."}, "recall": {"q": "Назови по памяти таблицу нестандартных разностей Δ и 4 элемента с |ВСО| = |НСО|.", "points": ["Стандартные неметаллы (C, Si, N, P, S, Cl, Br, I): Δ = 8.", "Нестандартные неметаллы: F → Δ = 1 ([−1; 0]); H → Δ = 2 ([−1; +1]); B → Δ = 3 ([0; +3]); O → Δ = 4 ([−2; +2]).", "Металлы: НСО = 0, поэтому Δ = ВСО (IA/Ag → 1; IIA/Zn/Cu → 2; Al/Sc → 3; Cr/Fe → 6; Mn → 7).", "Четыре элемента с |ВСО| = |НСО|: C (+4/−4), Si (+4/−4), O (+2/−2), H (+1/−1)."]}}, {"id": "val_period2", "name": "Валентность, возбуждение и потолок 2-го периода", "ref": "04", "idea": "Различать обменный и донорно-акцепторный механизмы, объяснять отсутствие 2d-орбиталей и потолок валентности N (IV), O (III), F (I) и не путать высшую валентность с высшей с.о.", "pre": {"type": "one", "q": "Почему фосфор образует PCl5 (валентность V), а стоящий над ним в той же VA-подгруппе азот никогда не бывает пятивалентным (максимум IV)?", "o": ["У азота на 2-м энергетическом уровне всего 4 орбитали (одна 2s и три 2p) и нет 2d-подуровня, поэтому он не может распарить 2s²-пару и образовать больше 4 связей", "У азота меньше валентных электронов, чем у фосфора", "Азот не способен образовывать донорно-акцепторные связи", "Азот не может проявлять степень окисления +5"], "a": 0, "ex": "На 2-м уровне существуют только 4 орбитали (2s + три 2p), поэтому азот не переходит в возбуждённое состояние: максимум 3 обменные + 1 донорно-акцепторная связь = валентность IV. У фосфора есть пустые 3d-орбитали, что даёт 5 связей (V).", "d": {"1": "И у N, и у P ровно по 5 валентных электронов (VA группа).", "2": "Напротив, именно за счёт 4-й донорно-акцепторной связи азот достигает валентности IV в NH4^{+} и HNO3.", "3": "Высшая с.о. азота равна +5 (в HNO3 и N2O5), но валентность при этом строго IV!"}}, "pair": {"type": "one", "cases": [["Азотная кислота HNO3", "Азот образует 4 связи (3 обменные + 1 донорно-акцепторная N → O): валентность IV, с.о. +5"], ["Фосфорная кислота H3PO4", "Фосфор распаривает 3s² на пустой 3d-подуровень и образует 5 обменных связей: валентность V, с.о. +5"]], "q": "Как различаются ответы для азота N в двух вопросах КИМ № 3: (А) «высшая ВАЛЕНТНОСТЬ не равна номеру группы» и (Б) «высшая СТЕПЕНЬ ОКИСЛЕНИЯ не равна номеру группы»?", "o": ["В вопросе (А) азот ПОДХОДИТ (высшая валентность IV ≠ V), а в вопросе (Б) азот НЕ подходит (высшая с.о. +5 = V)", "Азот подходит в обоих вопросах", "Азот не подходит ни в одном из этих вопросов", "В вопросе (А) азот не подходит, а в вопросе (Б) подходит"], "a": 0, "ex": "Это главная ловушка № 3 КИМ: у азота ВСО = +5 (совпадает с номером группы V), а высшая валентность = IV (НЕ совпадает с V)."}, "fade": {"q": "Заполни правила механизмов связи и потолка валентности 2-го периода:", "steps": ["Валентность всегда записывается {римскими цифрами без знака|арабскими цифрами со знаком}; связь за счёт неподелённой пары одного атома и пустой орбитали другого называется {донорно-акцепторной|обменной|ионной}.", "Элементы 2-го периода N, O и F {не переходят|легко переходят} в возбуждённое состояние, так как на 2-м уровне нет свободных {d-орбиталей|s-орбиталей|p-орбиталей}.", "Максимальная валентность азота равна {IV|V|III}, кислорода (с учётом донорно-акцепторной связи в H3O^{+} и CO) — {III|II|VI}, фтора — {I|VII|II}."]}, "bug": {"q": "Найди ошибочный шаг в разборе вопроса: «Выберите два элемента, у которых высшая валентность не равна номеру группы» для ряда 1) N  2) P  3) S  4) O  5) Cl:", "steps": ["У фосфора P (3-й период, VA) есть пустой 3d-подуровень → он достигает валентности V (= номеру группы).", "У серы S (3-й период, VIA) и хлора Cl (3-й период, VIIA) есть 3d-орбитали → их высшие валентности VI и VII (= номеру группы).", "У азота N в HNO3 степень окисления равна +5, значит и его высшая валентность равна V (= номеру группы), поэтому азот не подходит.", "У кислорода O (2-й период, VIA) нет 2d-орбиталей, поэтому его высшая валентность III (в H3O^{+}, CO) не равна VI."], "bad": 2, "fix": "У азота в HNO3 степень окисления +5, но высшая валентность строго IV (≠ V)! Поэтому правильная пара — N (1) и O (4) → ответ: 14.", "why": "Приравнивать высшую валентность азота к его высшей с.о. (+5) — антипаттерн, на котором ловят чаще всего."}, "recall": {"q": "Назови по памяти потолок валентности для N, O, F, C и объясни роль 3d-орбиталей у P, S, Cl.", "points": ["2-й период ограничен 4 орбиталями (2s + три 2p), 2d-подуровня нет.", "N (VA): обменная III, макс. IV (NH4^{+}, HNO3, N2O5), никогда не V.", "O (VIA): обменная II, макс. III (H3O^{+}, CO); F (VIIA): всегда только I; C (IVA): возбуждается до 2s¹2p³ → IV.", "P, S, Cl (3-й период) используют пустые 3d-орбитали → достигают валентностей V, VI, VII."]}}, {"id": "val_vs_so", "name": "Соотношение валентности и степени окисления", "ref": "05", "idea": "Мгновенно узнавать все 4 причины несовпадения валентности и |с.о.| в N2, H2O2, FeS2, CO, HNO3, NH4^{+}, H3O^{+}, H3PO2/H3PO3 и органическом ряду углерода.", "pre": {"type": "one", "q": "Чему равны валентность и степень окисления углерода в молекуле угарного газа CO?", "o": ["Валентность III, степень окисления +2", "Валентность II, степень окисления +2", "Валентность III, степень окисления +3", "Валентность IV, степень окисления +2"], "a": 0, "ex": "В CO между C и O тройная связь (2 обменные + 1 донорно-акцепторная от O к C), поэтому валентность обоих атомов равна III. При расчёте с.о. донорная пара кислорода остаётся у него, а 2 обменные пары смещены к O → C^{+2}, O^{−2}.", "d": {"1": "По обменному механизму связей 2, но третья (донорно-акцепторная O → C) увеличивает валентность до III.", "2": "Донорная пара принадлежала кислороду, поэтому при сдвиге к O она не даёт дополнительного заряда +1 на углероде.", "3": "У углерода в CO три связи (тройная связь C≡O), а не четыре."}}, "pair": {"type": "one", "cases": [["Пероксид водорода H—O—O—H", "У кислорода 2 связи (валентность II), но связь O—O неполярна → с.о. равна −1"], ["Формальдегид H2C=O", "У углерода 4 связи (валентность IV), но две C—H (−2) и две C=O (+2) взаимно гасятся → с.о. равна 0"]], "q": "В каком из приведённых веществ валентность подчёркнутого атома и модуль его степени окисления СОВПАДАЮТ?", "o": ["CO2 (углерод: валентность IV, с.о. +4)", "NH4^{+} (азот: валентность IV, с.о. −3)", "H2O2 (кислород: валентность II, с.о. −1)", "HNO3 (азот: валентность IV, с.о. +5)"], "a": 0, "ex": "В CO2 (O=C=O) все 4 связи углерода полярны и смещены в одну сторону — к более электроотрицательному кислороду, поэтому валентность IV совпадает с |+4| = 4."}, "fade": {"q": "Определи валентность и степень окисления центральных атомов в «звёздных» молекулах ЕГЭ:", "steps": ["В простом веществе N2 между атомами тройная неполярная связь: валентность азота равна {III|0|IV}, а степень окисления равна {0|−3|+3}.", "В катионе аммония NH4^{+} у азота валентность {IV|III|V} и степень окисления {−3|+4|−4}, а в ионе гидроксония H3O^{+} у кислорода валентность {III|II|IV} и степень окисления {−2|−3|+1}.", "В органическом ряду CH4 → CH3OH → HCHO → HCOOH → CO2 валентность углерода всегда равна {IV|II|меняется от IV до 0}, а его степень окисления меняется от {−4 до +4 (проходя через 0 в HCHO)|−4 до 0|0 до +4}."]}, "bug": {"q": "Найди ошибочный шаг в определении валентности и степени окисления атомов в молекулах H2O2, FeS2, HCHO и H3PO3:", "steps": ["В пероксиде водорода H2O2 у кислорода степень окисления −1, а валентность равна II (структура H—O—O—H).", "В пирите FeS2 у серы степень окисления −1, а валентность равна II (из-за связи —S—S—).", "В формальдегиде HCHO степень окисления углерода равна 0, следовательно, углерод не образует связей и его валентность равна 0.", "В фосфористой кислоте H3PO3 степень окисления фосфора равна +3, но его валентность равна V (есть прямая связь P—H и двойная P=O)."], "bad": 2, "fix": "В формальдегиде HCHO (H2C=O) углерод образует 4 ковалентные связи (валентность IV!), а с.о. 0 возникает из-за взаимной компенсации двух связей C—H (−2) и двойной связи C=O (+2).", "why": "Степень окисления 0 не означает отсутствия связей: в органике (HCHO, C6H12O6) и простых веществах (N2, O2) валентность ненулевая."}, "recall": {"q": "Перечисли по памяти 4 системные причины расхождения валентности и |с.о.| с одним примером на каждую.", "points": ["1. Простые вещества: N2 (вал. III, с.о. 0), O2 (II / 0).", "2. Неполярные связи Э—Э в сложных веществах: H2O2 (O: II / −1), FeS2 (S: II / −1), C2H6 (C: IV / −3), CaC2 (C: IV / −1).", "3. Донорно-акцепторные связи: CO (C: III / +2, O: III / −2), HNO3 (N: IV / +5), NH4^{+} (N: IV / −3), H3O^{+} (O: III / −2).", "4. Связи с атомами разной ЭО (разнонаправленные сдвиги): CH3OH (C: IV / −2), HCHO (C: IV / 0), HCOOH (C: IV / +2), H3PO2/H3PO3 (P: V / +1 и +3)."]}}, {"id": "d_exceptions", "name": "d-элементы и полный реестр исключений", "ref": "06", "idea": "Безошибочно определять характерные и высшие с.о. d-элементов (Sc, Ti, V, Cr, Mn, Fe, Cu, Zn, Ag) и различать списки «ВСО ≠ группе», «валентность ≠ группе» и «постоянная с.о.».", "pre": {"type": "one", "q": "У каких двух d-элементов 4-го периода высшая степень окисления в школьной модели ЕГЭ НЕ равна номеру группы?", "o": ["Железо Fe (VIIIБ, ВСО = +6) и медь Cu (IБ, ВСО = +2)", "Хром Cr (VIБ, ВСО = +6) и марганец Mn (VIIБ, ВСО = +7)", "Цинк Zn (IIБ, ВСО = +2) и скандий Sc (IIIБ, ВСО = +3)", "Железо Fe (VIIIБ, ВСО = +6) и цинк Zn (IIБ, ВСО = +2)"], "a": 0, "ex": "От Sc (+3) до Mn (+7), а также у Zn (+2) и Ag (+1) ВСО равна номеру группы. Нарушают правило именно Fe (+6 ≠ VIII, в ферратах K2FeO4) и Cu (+2 ≠ I, в CuO/CuSO4).", "d": {"1": "У Cr (+6 = VI) и Mn (+7 = VII) высшая с.о. точно равна номеру группы.", "2": "У Zn (+2 = II) и Sc (+3 = III) высшая с.о. точно равна номеру группы (и к тому же постоянна).", "3": "У Zn в IIБ группе постоянная и высшая с.о. равна +2, что совпадает с номером группы II."}}, "pair": {"type": "one", "cases": [["Водород H", "Постоянная валентность I (одна орбиталь 1s), но ПЕРЕМЕННАЯ степень окисления (+1 и −1)"], ["Цинк Zn и серебро Ag", "Постоянная степень окисления в соединениях (+2 у Zn и +1 у Ag в ЕГЭ)"]], "q": "Какая пара элементов имеет ПОСТОЯННУЮ степень окисления во всех своих соединениях в курсе ЕГЭ?", "o": ["Zn (+2) и F (−1)", "H (+1/−1) и Cu (+1/+2)", "O (−2/−1/+2) и Fe (+2/+3/+6)", "Zn (+2) и Cr (+2/+3/+6)"], "a": 0, "ex": "Полный список элементов с постоянной с.о. в соединениях на ЕГЭ: F (−1), Li–Cs (+1), Be–Ba (+2), Al (+3), Zn (+2), Ag (+1), Sc (+3). Водород, кислород, медь, железо и хром имеют переменную с.о.!"}, "fade": {"q": "Разведи три «золотых списка» исключений задания № 3:", "steps": ["Высшая СТЕПЕНЬ ОКИСЛЕНИЯ не равна номеру группы у {F, O, Fe, Cu (и инертных газов)|N, O, F, Fe, Cu}; азот в этот список {не входит|входит}, так как его ВСО равна +5.", "Высшая ВАЛЕНТНОСТЬ не равна номеру группы у {N, O, F, Fe, Cu|только у F и O}; азот сюда {входит|не входит}, так как его предел — IV.", "У цинка Zn (3d¹⁰4s²) в соединениях постоянная с.о. {+2|+1 и +2}, у серебра Ag в ЕГЭ — постоянная {+1|+1 и +2}, а у меди Cu — переменная {+1 и +2|только +1}."]}, "bug": {"q": "Найди ошибочный шаг в решении задачи: «Из ряда 1) Cr  2) Fe  3) Cu  4) Zn  5) N выберите два элемента, высшая степень окисления которых НЕ равна номеру группы»:", "steps": ["У хрома Cr (VIБ) высшая с.о. равна +6 (в K2CrO4) — равна номеру группы, не подходит.", "У цинка Zn (IIБ) высшая с.о. равна +2 (постоянная) — равна номеру группы, не подходит.", "У железа Fe (VIIIБ) высшая с.о. равна +6 (≠ VIII) — подходит.", "У азота N (VA) высшая валентность IV, значит он тоже не достигает номера группы, поэтому выбираем Fe (2) и N (5)."], "bad": 3, "fix": "В условии спрашивают про высшую СТЕПЕНЬ ОКИСЛЕНИЯ, а у азота ВСО = +5 (= V)! Вторым элементом является медь Cu (IБ, ВСО = +2 ≠ I). Правильный ответ: 23.", "why": "Классическая подмена «валентность» ↔ «степень окисления» на азоте и пропуск меди Cu (+2 в IБ группе)."}, "recall": {"q": "Назови по памяти карту 6 главных d-элементов ЕГЭ (Cr, Mn, Fe, Cu, Zn, Ag) и список элементов с постоянной с.о.", "points": ["Cr (VIБ): +2, +3, +6 (Δ = 6, ВСО = группе); Mn (VIIБ): +2, +3, +4, +6, +7 (Δ = 7, ВСО = группе).", "Fe (VIIIБ): +2, +3, +6 (Δ = 6, ВСО ≠ группе!); Cu (IБ): +1, +2 (Δ = 2, ВСО ≠ группе!).", "Zn (IIБ): постоянная +2 (Δ = 2); Ag (IБ): в ЕГЭ постоянная +1 (Δ = 1).", "Постоянная с.о. в соединениях: F (−1), IA (+1), IIA (+2), Al (+3), Zn (+2), Ag (+1), Sc (+3)."]}}, {"id": "oxo_hydrides", "name": "Оксоанионы ЭOₓ^{n−}, оксиды и водородные соединения", "ref": "07", "idea": "Применять двухшаговый фильтр (алгебра с.о. + реальное существование) к оксоанионам ЭOₓ^{n−} и высшим оксидам ЭₓOᵧ, а также отличать ЛВС от ионных гидридов.", "pre": {"type": "one", "q": "Почему из пары азот N и фосфор P ортоанион общей формулы ЭO4^{3−} образует только фосфор (PO4^{3−}), хотя оба элемента имеют степень окисления +5?", "o": ["Азот — маленький атом 2-го периода с потолком валентности IV, поэтому он даёт нитрат-ион NO3^{−}, но реального иона NO4^{3−} в химии ЕГЭ не существует", "В анионе ЭO4^{3−} требуется степень окисления +6, которой нет у азота", "Азот не образует кислородсодержащих кислот и их солей", "Фосфор имеет степень окисления +3 в PO4^{3−}"], "a": 0, "ex": "По алгебре s + 4·(−2) = −3 → s = +5, что подходит и N, и P. Но на 2-м шаге проверяем реальность иона: фосфор образует PO4^{3−}, а азот — только NO3^{−} (мета-форма).", "d": {"1": "В ЭO4^{3−}: s − 8 = −3 → s = +5 (а +6 требуется для ЭO4^{2−}).", "2": "Азот образует HNO3 (NO3^{−}) и HNO2 (NO2^{−}).", "3": "В PO4^{3−} у фосфора высшая степень окисления +5 (+5 − 8 = −3)."}}, "pair": {"type": "one", "cases": [["Анион ЭO4^{2−} (с.о. +6)", "Реальные ионы ЕГЭ: SO4^{2−}, CrO4^{2−}, MnO4^{2−} (манганат!), FeO4^{2−} (феррат!)"], ["Анион ЭO4^{−} (с.о. +7)", "Реальные ионы ЕГЭ: MnO4^{−} (перманганат), ClO4^{−}, BrO4^{−}, IO4^{−}"]], "q": "Какая пара элементов образует устойчивые оксоанионы общей формулы ЭO4^{2−}?", "o": ["Mn (манганат MnO4^{2−}) и Cr (хромат CrO4^{2−})", "Mn (перманганат MnO4^{−}) и Cl (перхлорат ClO4^{−})", "S (сульфат SO4^{2−}) и P (фосфат PO4^{3−})", "C (карбонат CO3^{2−}) и Si (силикат SiO3^{2−})"], "a": 0, "ex": "В ЭO4^{2−} степень окисления элемента равна +6. Из всех пар именно Mn (K2MnO4) и Cr (K2CrO4) образуют ионы ЭO4^{2−} (а также S и Fe)."}, "fade": {"q": "Восстанови правила двухшаговой проверки для оксоанионов, высших оксидов и водородных соединений:", "steps": ["Для оксоаниона ЭOₓ^{n−} сначала вычисляем с.о. элемента s = {2x − n|2x + n|x − n}, а затем проверяем {существует ли реальная соль с таким анионом в ЕГЭ|совпадает ли s с номером периода}.", "Летучие водородные соединения (ЛВС) образуют только {неметаллы IVA–VIIA групп|все элементы таблицы|активные металлы IA–IIA групп}; гидриды NaH и CaH2 к ЛВС {не относятся|относятся}.", "Фтор F {не образует оксидов|образует высший оксид F2O7}, а железо Fe проявляет +6 в {ферратах (K2FeO4)|оксиде FeO3}."]}, "bug": {"q": "Найди ошибочный шаг в решении задачи: «Из ряда 1) Si  2) P  3) S  4) Na  5) Cr выберите два элемента, образующих оксоанион ЭO4^{2−}»:", "steps": ["Вычисляем степень окисления элемента в ЭO4^{2−}: s + 4·(−2) = −2 → s = +6.", "Na (щелочной металл, оксоанионов не даёт) и Si (максимум +4) сразу отсеиваются.", "Проверяем S (SO4^{2−}, с.о. +6) — подходит.", "Проверяем P (образует ион PO4^{3−} с четырьмя кислородами) — значит подходит пара S (3) и P (2)."], "bad": 3, "fix": "У фосфата PO4^{3−} заряд равен 3− (а не 2−!), и с.о. фосфора +5 (а не +6). Второй верный элемент — хром Cr (хромат CrO4^{2−}, с.о. +6). Ответ: 35.", "why": "Нельзя смотреть только на индекс 4 у кислорода: нужно обязательно проверять заряд аниона и степень окисления!"}, "recall": {"q": "Назови по памяти 4 главные формулы оксоанионов ЕГЭ и 3 правила про ЛВС и оксиды.", "points": ["ЭO4^{2−} (+6): SO4^{2−}, CrO4^{2−}, MnO4^{2−}, FeO4^{2−}; ЭO4^{−} (+7): MnO4^{−}, ClO4^{−}.", "ЭO3^{−} (+5): NO3^{−}, ClO3^{−}, BrO3^{−}, PO3^{−}; ЭO3^{2−} (+4): CO3^{2−}, SiO3^{2−}, SO3^{2−}; ЭO2^{−} (+3): NO2^{−}, ClO2^{−}, AlO2^{−}, CrO2^{−}.", "ЛВС дают только неметаллы IVA–VIIA; NaH и CaH2 — нелетучие ионные гидриды; в SiH4 у кремния +4.", "Фтор не образует оксидов (OF2 — фторид кислорода); у железа нет высшего оксида FeO3 (только ферраты FeO4^{2−})."]}}, {"id": "kim3_strategy", "name": "Боевая стратегия и все 12 формулировок № 3 КИМ", "ref": "08", "idea": "Мгновенно считывать слова-переключатели в любой из 12 формулировок задания № 3 ФИПИ и решать его за 60 секунд по 4-шаговому алгоритму с проверкой отбракованных элементов.", "pre": {"type": "one", "q": "Как оценивается и оформляется ответ в задании № 3 КИМ ЕГЭ по химии?", "o": ["Даёт 1 первичный балл; в ответе всегда ровно две цифры без пробелов, порядок цифр значения не имеет (14 и 41 оба верны)", "Даёт 2 первичных балла; порядок двух цифр строго важен", "Даёт 1 первичный балл; в ответе три цифры в строгом порядке", "Даёт 2 первичных балла; можно записать от двух до четырёх цифр"], "a": 0, "ex": "Задание № 3 — базового уровня (1 балл), всегда ровно 2 элемента (2 цифры), и в отличие от задания № 2 порядок цифр значения не имеет.", "d": {"1": "Задание № 3 оценивается в 1 балл, а порядок цифр не важен.", "2": "Три цифры в строгом порядке — это формат задания № 2 (код 1.2), а не № 3.", "3": "В задании № 3 всегда ровно две цифры."}}, "pair": {"type": "one", "cases": [["Переключатель: «в соединениях проявляют только отрицательную с.о.»", "Исключает ноль простого вещества → подходит только фтор F (−1)"], ["Переключатель: «не проявляют положительной с.о.»", "Допускает 0 и отрицательные → подходят фтор F (−1, 0) и инертные газы (0)"]], "q": "Какое слово-переключатель в условии задания № 3 критически меняет судьбу элемента азота N (VA группа)?", "o": ["Различие между «высшая ВАЛЕНТНОСТЬ не равна номеру группы» (N подходит: IV ≠ V) и «высшая СТЕПЕНЬ ОКИСЛЕНИЯ не равна номеру группы» (N не подходит: +5 = V)", "Различие между «одинаковая высшая с.о.» и «одинаковая разность Δ»", "Различие между «в соединениях» и «в простых веществах»", "Различие между «летучее водородное соединение» и «гидрид»"], "a": 0, "ex": "Именно пара слов «валентность» vs «степень окисления» переключает ответ для азота на противоположный."}, "fade": {"q": "Закрепи 4-шаговый алгоритм решения задания № 3 КИМ:", "steps": ["Шаг 1: подчеркни в условии слово-переключатель ({валентность vs с.о., «в соединениях», «не равна», оксоанион|только названия элементов}).", "Шаг 2: подпиши над всеми пятью элементами ряда их {группу и паспорт [НСО; ВСО]|относительную атомную массу}.", "Шаг 3–4: отбери ровно {два|три} элемента и обязательно проверь, что {оставшиеся три элемента точно не подходят|цифры стоят строго по убыванию}."]}, "bug": {"q": "Найди ошибочный шаг в решении задачи: «Из ряда 1) O  2) F  3) S  4) N  5) Cl выберите два элемента, которые могут проявлять степень окисления −1 в сложных веществах»:", "steps": ["Фтор F (2) в любых соединениях имеет с.о. −1 — подходит.", "Хлор Cl (5) в хлоридах и HCl имеет с.о. −1 — подходит.", "Останавливаемся на паре 25 и не проверяем оставшиеся элементы O, S, N.", "Контрольная проверка всех пяти элементов обязательна: если подходит больше двух, значит в условии есть уточнение или ошибка в прочтении."], "bad": 2, "fix": "Если бы мы проверили оставшиеся элементы, увидели бы, что O (−1 в H2O2), S (−1 в FeS2) и N (−1 в NH2OH) тоже бывают −1! В реальном КИМ проверяют все 5 элементов до конца, чтобы убедиться, что ровно два соответствуют точному условию (например, «низшая с.о. равна −1» → только F и Cl).", "why": "Шаг 4 алгоритма (проверка трёх отброшенных элементов) мгновенно ловит неверно прочитанное слово-переключатель (например, «низшая с.о. = −1» вместо «могут проявлять −1»)."}, "recall": {"q": "Назови по памяти 4 шага боевого алгоритма КИМ № 3 и 4 главных слова-переключателя.", "points": ["4 шага: 1) подчеркнуть переключатель; 2) выписать паспорт [НСО; ВСО] всех 5 элементов; 3) отобрать 2; 4) проверить, что остальные 3 не подходят.", "Переключатель 1: «валентность» (N = IV ≠ V) vs «степень окисления» (N = +5 = V).", "Переключатель 2: «в соединениях» (исключает 0 простого вещества) vs «в целом» (включает 0).", "Переключатель 3 и 4: «летучее водородное соединение» (только IVA–VIIA, без металлов; SiH4 = +4!) и «оксоанион ЭOₓ^{n−}» (алгебра + реальность)."]}}], "figs": {}, "tab": [{"id": "t_eo_binaries", "t": "Степени окисления в ключевых бинарных соединениях (границы ЭО)", "k": "Соединение", "km": "соединением", "ref": "01.17", "n": 3, "lv3": ["OF2 (фторид кислорода)", "SiH4 (силан)", "PH3 (фосфин, традиция ЕГЭ)", "B2H6 (диборан)", "FeS2 (пирит)"], "cols": [{"t": "Элемент с отрицательной с.о.", "sk": "eo_shift", "n": 3, "q": "Какой элемент имеет ОТРИЦАТЕЛЬНУЮ степень окисления в соединении {x}?", "m": "элементом с отрицательной с.о.", "mq": "Выберите {k} соединения, в которых отрицательную с.о. имеет «{v}»:"}, {"t": "Степени окисления элементов", "sk": "so_calc", "n": 3, "q": "Каковы степени окисления элементов в веществе {x}?", "m": "степенями окисления элементов"}], "rows": [["OF2 (фторид кислорода)", "Фтор (F)", "O^{+2}, F^{−1}"], ["SiH4 (силан)", "Водород (H)", "Si^{+4}, H^{−1}"], ["NaH (гидрид натрия)", "Водород (H)", "Na^{+1}, H^{−1}"], ["B2H6 (диборан)", "Водород (H)", "B^{+3}, H^{−1}"], ["CH4 (метан)", "Углерод (C)", "C^{−4}, H^{+1}"], ["PH3 (фосфин, традиция ЕГЭ)", "Фосфор (P)", "P^{−3}, H^{+1}"], ["H2O2 (пероксид водорода)", "Кислород (O)", "H^{+1}, O^{−1}"], ["FeS2 (пирит)", "Сера (S)", "Fe^{+2}, S^{−1}"]], "rw": {"OF2 (фторид кислорода)": "Фтор электроотрицательнее кислорода (3,98 > 3,44), поэтому кислород положителен (+2).", "SiH4 (силан)": "ЭО(H) = 2,20 > ЭО(Si) = 1,90 → кремний +4, водород −1!", "PH3 (фосфин, традиция ЕГЭ)": "По школьной традиции ЕГЭ для фосфина принимают P^{−3} и H^{+1}."}}, {"id": "t_delta_map", "t": "Диапазоны [НСО; ВСО] и разность Δ для элементов и исключений", "k": "Элемент", "km": "элементом", "ref": "03.14", "n": 3, "lv3": ["O (кислород)", "F (фтор)", "H (водород)", "B (бор, модель ЕГЭ)", "Fe (железо)", "Cu (медь)"], "cols": [{"t": "Низшая с.о. (НСО)", "sk": "delta_range", "n": 3, "q": "Чему равна НИЗШАЯ степень окисления (НСО) элемента {x} в школьной модели ЕГЭ?", "m": "низшей степенью окисления", "mq": "Выберите {k} элемента с низшей степенью окисления «{v}»:"}, {"t": "Высшая с.о. (ВСО)", "sk": "delta_range", "n": 3, "q": "Чему равна ВЫСШАЯ степень окисления (ВСО) элемента {x} в школьной модели ЕГЭ?", "m": "высшей степенью окисления", "mq": "Выберите {k} элемента с высшей степенью окисления «{v}»:"}, {"t": "Разность Δ = ВСО − НСО", "sk": "delta_range", "n": 3, "q": "Чему равна алгебраическая разность Δ = ВСО − НСО для элемента {x}?", "m": "разностью Δ = ВСО − НСО", "mq": "Выберите {k} элемента с разностью Δ = «{v}»:"}], "rows": [["C (углерод)", "−4", "+4", "8"], ["Si (кремний)", "−4", "+4", "8"], ["N (азот)", "−3", "+5", "8"], ["S (сера)", "−2", "+6", "8"], ["Cl (хлор)", "−1", "+7", "8"], ["O (кислород)", "−2", "+2", "4"], ["F (фтор)", "−1", "0", "1"], ["H (водород)", "−1", "+1", "2"], ["B (бор, модель ЕГЭ)", "0", "+3", "3"], ["Na (натрий)", "0", "+1", "1"], ["Mg (магний)", "0", "+2", "2"], ["Al (алюминий)", "0", "+3", "3"], ["Cr (хром)", "0", "+6", "6"], ["Fe (железо)", "0", "+6", "6"], ["Cu (медь)", "0", "+2", "2"], ["Mn (марганец)", "0", "+7", "7"]], "rw": {"O (кислород)": "ВСО кислорода +2 (в OF2), НСО −2 → Δ = +2 − (−2) = 4.", "F (фтор)": "ВСО фтора 0 (в F2), НСО −1 → Δ = 0 − (−1) = 1 (как у Na и Ag!).", "H (водород)": "ВСО +1, НСО −1 → Δ = +1 − (−1) = 2 (как у Mg, Zn, Cu!).", "B (бор, модель ЕГЭ)": "Формула N − 8 к бору в ЕГЭ не применяется: НСО = 0, ВСО = +3, Δ = 3 (как у Al!).", "Fe (железо)": "ВСО железа в ЕГЭ +6 (ферраты), НСО 0 → Δ = 6 (как у Cr!)."}}, {"id": "t_val_vs_so_stars", "t": "«Звёздные» молекулы ЕГЭ: валентность против степени окисления", "k": "Вещество (атом)", "km": "веществом", "ref": "05.4", "n": 3, "lv3": ["HNO3 (атом N)", "CO (атом C)", "CO (атом O)", "H3O^{+} (атом O)", "HCHO (атом C)", "H3PO3 (атом P)", "FeS2 (атом S)"], "cols": [{"t": "Валентность атома", "sk": "val_vs_so", "n": 3, "q": "Чему равна ВАЛЕНТНОСТЬ указанного атома в {x}?", "m": "валентностью атома", "mq": "Выберите {k} случая с валентностью атома «{v}»:"}, {"t": "Степень окисления атома", "sk": "val_vs_so", "n": 3, "q": "Чему равна СТЕПЕНЬ ОКИСЛЕНИЯ указанного атома в {x}?", "m": "степенью окисления атома", "mq": "Выберите {k} случая со степенью окисления «{v}»:"}], "rows": [["N2 (атом N)", "III", "0"], ["HNO3 (атом N)", "IV", "+5"], ["NH4^{+} (атом N)", "IV", "−3"], ["CO (атом C)", "III", "+2"], ["CO (атом O)", "III", "−2"], ["H3O^{+} (атом O)", "III", "−2"], ["H2O2 (атом O)", "II", "−1"], ["FeS2 (атом S)", "II", "−1"], ["CH3OH (атом C)", "IV", "−2"], ["HCHO (атом C)", "IV", "0"], ["H3PO3 (атом P)", "V", "+3"]], "rw": {"HNO3 (атом N)": "Потолок 2-го периода: валентность N строго IV, но с.о. +5.", "CO (атом C)": "Тройная связь (2 обменные + 1 донорно-акцепторная O → C): валентность III, с.о. +2.", "HCHO (атом C)": "В формальдегиде у углерода 4 связи (IV), но сдвиги C—H (−2) и C=O (+2) дают с.о. 0.", "H3PO3 (атом P)": "Есть прямая связь P—H и двойная P=O → валентность P равна V при с.о. +3."}}, {"id": "t_d_elements_map", "t": "Карта d-элементов для задания № 3 ЕГЭ", "k": "d-элемент (группа)", "km": "элементом", "ref": "06.7", "n": 3, "lv3": ["Fe (VIIIБ)", "Cu (IБ)", "Zn (IIБ)", "Ag (IБ)", "Cr (VIБ)", "Mn (VIIБ)"], "cols": [{"t": "ВСО = номеру группы?", "sk": "d_exceptions", "n": 3, "q": "Совпадает ли высшая степень окисления элемента {x} с номером его группы в школьной модели ЕГЭ?", "m": "совпадением ВСО с номером группы", "mq": "Выберите {k} d-элемента, для которых ответ на вопрос «ВСО = номеру группы?»: «{v}»:"}, {"t": "Тип степени окисления", "sk": "d_exceptions", "n": 3, "q": "Постоянную или переменную степень окисления в соединениях проявляет элемент {x} в курсе ЕГЭ?", "m": "типом степени окисления (постоянная / переменная)", "mq": "Выберите {k} d-элемента с характеристикой «{v}»:"}, {"t": "Высшая с.о. в ЕГЭ", "sk": "d_exceptions", "n": 3, "q": "Чему равна высшая степень окисления d-элемента {x} в школьной модели ЕГЭ?", "m": "высшей степенью окисления", "mq": "Выберите {k} d-элемента с высшей степенью окисления «{v}»:"}], "rows": [["Sc (IIIБ)", "Да", "Постоянная", "+3"], ["Cr (VIБ)", "Да", "Переменная", "+6"], ["Mn (VIIБ)", "Да", "Переменная", "+7"], ["Fe (VIIIБ)", "Нет", "Переменная", "+6"], ["Cu (IБ)", "Нет", "Переменная", "+2"], ["Zn (IIБ)", "Да", "Постоянная", "+2"], ["Ag (IБ)", "Да", "Постоянная", "+1"]], "rw": {"Fe (VIIIБ)": "Железо в ЕГЭ не достигает +8: максимум +6 (в ферратах K2FeO4).", "Cu (IБ)": "У меди высшая и самая устойчивая с.о. равна +2 (выше номера группы I).", "Zn (IIБ)": "Завершённый 3d¹⁰-подуровень не участвует в связях → постоянная с.о. +2."}}, {"id": "t_oxoanions_fipi", "t": "Шпаргалка реальных оксоанионов ЭOₓ^{n−} ЕГЭ", "k": "Общая формула аниона", "km": "формулой аниона", "ref": "07.6", "n": 3, "lv3": ["ЭO4^{2−}", "ЭO4^{−}", "ЭO4^{3−}", "ЭO2^{−}", "ЭO2^{2−}"], "cols": [{"t": "Требуемая с.о. Э", "sk": "oxo_hydrides", "n": 3, "q": "Какую степень окисления должен иметь элемент Э в оксоанионе {x}?", "m": "требуемой степенью окисления Э", "mq": "Выберите {k} формулы оксоанионов, в которых с.о. элемента Э равна «{v}»:"}, {"t": "Реальные примеры ЕГЭ", "sk": "oxo_hydrides", "n": 3, "q": "Какие реальные анионы из курса ЕГЭ соответствуют общей формуле {x}?", "m": "реальными примерами анионов"}], "rows": [["ЭO^{−}", "+1", "ClO^{−}, BrO^{−}, IO^{−}"], ["ЭO2^{−}", "+3", "NO2^{−}, ClO2^{−}, AlO2^{−}, CrO2^{−}, FeO2^{−}"], ["ЭO3^{−}", "+5", "NO3^{−}, ClO3^{−}, BrO3^{−}, IO3^{−}, PO3^{−}"], ["ЭO4^{−}", "+7", "MnO4^{−}, ClO4^{−}, BrO4^{−}, IO4^{−}"], ["ЭO2^{2−}", "+2", "ZnO2^{2−}, BeO2^{2−}, PbO2^{2−}"], ["ЭO3^{2−}", "+4", "CO3^{2−}, SiO3^{2−}, SO3^{2−}"], ["ЭO4^{2−}", "+6", "SO4^{2−}, CrO4^{2−}, MnO4^{2−}, FeO4^{2−}"], ["ЭO4^{3−}", "+5", "PO4^{3−}, AsO4^{3−} (но НЕ NO4^{3−}!)"]], "rw": {"ЭO4^{2−}": "Не забывай зелёный манганат MnO4^{2−} и фиолетовый феррат FeO4^{2−}!", "ЭO4^{3−}": "Азот имеет +5, но аниона NO4^{3−} не образует (только NO3^{−})."}}], "rx": [], "seq": [{"id": "sq_eo_row", "sk": "eo_shift", "ref": "01.15", "n": 3, "lvl": 3, "q": "Расположите элементы в порядке ВОЗРАСТАНИЯ их электроотрицательности (от самого слабого к самому сильному, по рабочему ряду ЕГЭ):", "items": ["Si (1,90)", "B (2,04)", "H (2,20)", "C (2,55)", "N (3,04)", "Cl (3,16)", "O (3,44)", "F (3,98)"], "why": "Ключевые границы рабочего ряда: Si < B < H < C < N < Cl < O < F. Кислород сильнее хлора, а водород сильнее кремния и бора."}, {"id": "sq_delta_asc", "sk": "delta_range", "ref": "03.14", "n": 3, "lvl": 3, "q": "Расположите элементы в порядке ВОЗРАСТАНИЯ разности Δ = ВСО − НСО (от наименьшей к наибольшей):", "items": ["F (0 − (−1) = 1)", "H (+1 − (−1) = 2)", "Al (+3 − 0 = 3)", "O (+2 − (−2) = 4)", "Fe (+6 − 0 = 6)", "Mn (+7 − 0 = 7)", "S (+6 − (−2) = 8)"], "why": "У исключений и металлов Δ меньше 8: F (1) < H (2) < Al (3) < O (4) < Fe (6) < Mn (7) < S (8)."}, {"id": "sq_carbon_org", "sk": "val_vs_so", "ref": "05.7", "n": 3, "lvl": 2, "q": "Расположите соединения углерода (в каждом из которых его валентность равна IV) в порядке ВОЗРАСТАНИЯ степени окисления углерода:", "items": ["CH4 (с.о. углерода −4)", "CH3OH (с.о. углерода −2)", "HCHO (с.о. углерода 0)", "HCOOH (с.о. углерода +2)", "CO2 (с.о. углерода +4)"], "why": "По мере замены связей C—H на связи C—O степень окисления углерода растёт с шагом +2: −4 → −2 → 0 → +2 → +4 при неизменной валентности IV."}, {"id": "sq_val_ceiling", "sk": "val_period2", "ref": "04.12", "n": 3, "lvl": 2, "q": "Расположите элементы в порядке ВОЗРАСТАНИЯ их максимальной валентности в соединениях (с учётом донорно-акцепторного механизма):", "items": ["F (макс. валентность I)", "O (макс. валентность III в H3O^{+} и CO)", "N (макс. валентность IV в NH4^{+} и HNO3)", "P (макс. валентность V за счёт 3d)", "S (макс. валентность VI за счёт 3d)", "Cl (макс. валентность VII за счёт 3d)"], "why": "У элементов 2-го периода потолок задан отсутствием 2d-орбиталей (F = I < O = III < N = IV), а элементы 3-го периода достигают номера группы (P = V < S = VI < Cl = VII)."}, {"id": "sq_oxo_filter", "sk": "oxo_hydrides", "ref": "07.4", "n": 3, "lvl": 2, "q": "Установите правильную последовательность шагов проверки, образует ли элемент Э оксоанион общей формулы ЭOₓ^{n−}:", "items": ["Вычислить требуемую степень окисления элемента Э из уравнения s + x·(−2) = −n", "Проверить, способен ли данный элемент проявлять найденную положительную степень окисления", "Проверить, способен ли элемент в этой с.о. давать кислотный оксид (отсеять щелочные/щёлочноземельные металлы и фтор)", "Убедиться, что в курсе ЕГЭ реально существует анион именно с таким числом атомов кислорода x (отсеять NO4^{3−}, CO4^{4−})"], "why": "Многоступенчатый фильтр защищает от «чистой алгебры», которая ошибочно пропускает несуществующие ионы вроде NO4^{3−}."}, {"id": "sq_kim3_algo", "sk": "kim3_strategy", "ref": "08.3", "n": 3, "lvl": 1, "q": "Установите правильную последовательность шагов единого алгоритма решения любого задания № 3 КИМ:", "items": ["Прочитать условие и подчеркнуть слово-переключатель (валентность vs с.о., «в соединениях», «не равна», оксоанион)", "Выписать над всеми пятью элементами ряда группу, паспорт [НСО; ВСО] и при необходимости Δ или макс. валентность", "Отобрать ровно два элемента, сверяясь со списком исключений (F, O, N, H, B, Si, Fe, Cu, Zn)", "Проверить оставшиеся три элемента и убедиться, что они точно НЕ подходят под условие"], "why": "Контрольная проверка трёх отброшенных элементов на 4-м шаге гарантирует, что слово-переключатель прочитано верно."}], "facts": [{"id": "f_eo_so", "sk": "eo_shift", "ref": "01.18", "n": 3, "lvl": 3, "t": "Электроотрицательность и расчёт степеней окисления", "s": [["Фтор — самый электроотрицательный элемент: в любых соединениях он имеет с.о. −1 и никогда не бывает положительным.", "Фтор в соединении OF2 имеет степень окисления +1, а кислород — −2.", "ЭО(F) = 3,98 > ЭО(O) = 3,44, поэтому в OF2 строго O^{+2} и F^{−1}."], ["В силане SiH4 степень окисления кремния равна +4, а водорода −1, потому что ЭО(H) > ЭО(Si).", "В силане SiH4, как и в метане CH4, степень окисления элемента IVA группы равна −4.", "ЭО(H) = 2,20 > ЭО(Si) = 1,90, поэтому электроны в SiH4 смещены к водороду (Si^{+4}, H^{−1})."], ["В стандарте ФИПИ степень окисления пишут со знаком впереди (Fe^{+3}), а заряд иона — с цифрой впереди (Fe^{3+}, SO4^{2−}).", "В задании № 30 ЕГЭ запись заряда иона SO4^{-2} и запись SO4^{2−} считаются равнозначными.", "Запись заряда иона со знаком впереди в ионном уравнении № 30 обнуляет балл."], ["В пирите FeS2 железо имеет степень окисления +2, а сера — −1 из-за связи —S—S—.", "В пирите FeS2 железо имеет степень окисления +4, а сера — −2.", "Пирит состоит из Fe^{2+} и аниона S2^{2−}; в сумме +2 + 2·(−1) = 0."], ["В нитрате аммония NH4NO3 два атома азота имеют разные степени окисления: −3 в NH4^{+} и +5 в NO3^{−}.", "В нитрате аммония NH4NO3 оба атома азота имеют одинаковую степень окисления +1.", "Атомы азота входят в разные ионы, поэтому усреднять их в +1 нельзя."]]}, {"id": "f_delta_bounds", "sk": "delta_range", "ref": "03.16", "n": 3, "lvl": 3, "t": "Высшая, низшая степень окисления и разность Δ", "s": [["У всех стандартных неметаллов (C, Si, N, P, S, Cl, Br, I) разность Δ = ВСО − НСО равна ровно 8.", "У серы S (VIA) разность между высшей и низшей с.о. равна 4 (6 − 2 = 4).", "Вычитание отрицательного числа превращается в сложение: +6 − (−2) = 8."], ["Для всех металлов и для бора B (в модели ЕГЭ) низшая степень окисления равна 0, а отрицательных с.о. нет.", "Низшая степень окисления бора (IIIA) и алюминия (IIIA) рассчитывается по формуле 3 − 8 = −5.", "Формула N − 8 применяется только к неметаллам IVA–VIIA групп."], ["Условию |ВСО| = |НСО| в школьном курсе ЕГЭ удовлетворяют ровно четыре элемента: C, Si, O и H.", "Условию |ВСО| = |НСО| удовлетворяют только углерод C и кремний Si.", "Помимо C (±4) и Si (±4), подходят кислород O (+2 и −2) и водород H (+1 и −1)."], ["Фтор F и натрий Na имеют одинаковую разность между высшей и низшей с.о., равную 1.", "Фтор F не может иметь такую же разность Δ, как щелочной металл натрий Na.", "Для F: 0 − (−1) = 1; для Na: +1 − 0 = 1 — разности совпадают!"], ["Кислород O в соединениях может проявлять как отрицательную (−2, −1), так и положительную (+2, +1) степень окисления.", "Кислород в соединениях проявляет исключительно отрицательные степени окисления.", "Во фториде кислорода OF2 у кислорода с.о. +2 (а в O2F2 — +1)."]]}, {"id": "f_val_period2", "sk": "val_period2", "ref": "04.13", "n": 3, "lvl": 3, "t": "Валентность, потолок 2-го периода и расхождения с с.о.", "s": [["У азота N высшая валентность равна IV (не равна номеру группы V), а высшая степень окисления равна +5 (равна номеру группы V).", "У азота в азотной кислоте HNO3 и валентность (V), и степень окисления (+5) равны номеру группы.", "На 2-м уровне у азота нет 2d-орбиталей (всего 4 орбитали), поэтому азот не бывает пятивалентным."], ["В угарном газе CO валентность углерода и кислорода равна III, а степени окисления — +2 и −2.", "В угарном газе CO углерод и кислород двухвалентны, так как их степени окисления равны +2 и −2.", "Между C и O тройная связь (2 обменные + 1 донорно-акцепторная O → C), поэтому валентность равна III."], ["В формальдегиде HCHO и глюкозе C6H12O6 углерод имеет валентность IV и степень окисления 0.", "Степень окисления 0 возможна исключительно в простых веществах.", "В органике сдвиги полярных связей C—H и C=O могут взаимно компенсироваться, давая с.о. 0 при валентности IV."], ["В катионе гидроксония H3O^{+} кислород проявляет максимальную для себя валентность III при степени окисления −2.", "Максимальная валентность кислорода в соединениях равна II.", "За счёт неподелённой пары кислород образует третью (донорно-акцепторную) связь в H3O^{+} и CO → валентность III."], ["В фосфористой кислоте H3PO3 фосфор имеет валентность V, но степень окисления +3.", "В H3PO3 валентность фосфора равна III, поскольку его степень окисления равна +3.", "В молекуле H3PO3 есть прямая связь P—H и двойная P=O, всего 5 связей (валентность V)."]]}, {"id": "f_d_and_lists", "sk": "d_exceptions", "ref": "06.14", "n": 3, "lvl": 3, "t": "d-элементы и три списка исключений", "s": [["В школьной модели ЕГЭ высшая степень окисления железа равна +6 (в ферратах), а меди — +2 (обе не равны номеру группы).", "Высшая степень окисления железа (VIIIБ) равна +8, а меди (IБ) — +1.", "У Fe максимум +6 (K2FeO4), у Cu максимум +2 (CuO, CuSO4)."], ["У цинка Zn (+2) и серебра Ag (+1) в школьном курсе ЕГЭ постоянная степень окисления в соединениях.", "Цинк и серебро, как и все d-элементы, проявляют в ЕГЭ переменную степень окисления.", "У Zn прочный 3d¹⁰-подуровень даёт только +2; у Ag в ЕГЭ рассматривается только +1."], ["У водорода H постоянная валентность I, но переменная степень окисления (+1 и −1).", "Поскольку у водорода всего один электрон, он имеет постоянную степень окисления в соединениях.", "Водород может как отдавать электрон (+1 в H2O), так и принимать его (−1 в NaH, SiH4)."], ["У хрома Cr (VIБ) и железа Fe (VIIIБ) одинаковая разность между высшей и низшей степенями окисления, равная 6.", "Разность Δ у железа равна 8, а у хрома — 6.", "И у Cr, и у Fe диапазон [0; +6], поэтому Δ = 6 − 0 = 6."], ["В список «высшая с.о. не равна номеру группы» входят F, O, Fe, Cu (и инертные газы), но НЕ входит азот N.", "Азот N входит в список элементов, у которых высшая степень окисления не равна номеру группы.", "Высшая с.о. азота +5 равна номеру группы V; не равна группе его высшая ВАЛЕНТНОСТЬ (IV)."]]}, {"id": "f_oxo_lvs", "sk": "oxo_hydrides", "ref": "07.12", "n": 3, "lvl": 3, "t": "Оксоанионы, высшие оксиды и водородные соединения", "s": [["Марганец образует два разных оксоаниона: фиолетовый перманганат MnO4^{−} (+7) и зелёный манганат MnO4^{2−} (+6).", "Марганец образует только анион ЭO4^{−} (MnO4^{−}) и не образует аниона состава ЭO4^{2−}.", "Соли K2MnO4 (манганаты) содержат анион MnO4^{2−} со степенью окисления марганца +6."], ["Азот имеет степень окисления +5, но аниона состава ЭO4^{3−} (NO4^{3−}) в курсе ЕГЭ не образует.", "И азот, и фосфор образуют ортоанионы состава ЭO4^{3−}, так как оба находятся в VA группе.", "ЭO4^{3−} образуют P (PO4^{3−}) и As (AsO4^{3−}), а азот даёт только NO3^{−}."], ["Летучие водородные соединения (ЛВС) образуют только неметаллы IVA–VIIA групп; NaH и CaH2 к ЛВС не относятся.", "Гидрид натрия NaH и гидрид кальция CaH2 являются летучими водородными соединениями.", "NaH и CaH2 — твёрдые нелетучие солеобразные (ионные) гидриды."], ["Фтор не образует оксидов, а вещество OF2 называется фторидом кислорода.", "Высшим оксидом фтора является соединение OF2.", "Оксидами называют соединения, где кислород имеет отрицательную с.о. −2, а в OF2 у кислорода +2."], ["Железо проявляет степень окисления +6 в ферратах (FeO4^{2−}), но высшего оксида FeO3 в курсе ЕГЭ не образует.", "Высший оксид железа имеет общую формулу ЭO3 (FeO3).", "Для железа в ЕГЭ характерны оксиды FeO, Fe2O3 и Fe3O4; оксид FeO3 не существует."]]}], "calc": [{"id": "c_delta_nonmetals", "sk": "delta_range", "ref": "03.10", "n": 3, "lvl": 2, "v": {"_": [{"el": "серы (S, VIA)", "hi": 6, "lo": -2}, {"el": "азота (N, VA)", "hi": 5, "lo": -3}, {"el": "хлора (Cl, VIIA)", "hi": 7, "lo": -1}, {"el": "углерода (C, IVA)", "hi": 4, "lo": -4}, {"el": "кислорода (O, исключение)", "hi": 2, "lo": -2}, {"el": "фтора (F, исключение)", "hi": 0, "lo": -1}, {"el": "водорода (H, исключение)", "hi": 1, "lo": -1}, {"el": "бора (B, модель ЕГЭ)", "hi": 3, "lo": 0}, {"el": "железа (Fe, VIIIБ, исключение)", "hi": 6, "lo": 0}, {"el": "меди (Cu, IБ, исключение)", "hi": 2, "lo": 0}, {"el": "марганца (Mn, VIIБ)", "hi": 7, "lo": 0}]}, "q": "Вычислите разность Δ = ВСО − НСО между высшей и низшей степенями окисления {=el} в школьной модели ЕГЭ:", "a": "hi - lo", "dp": 0, "unit": "", "ex": "У {=el} высшая с.о. равна {=hi}, низшая с.о. равна {=lo}. Алгебраическая разность: Δ = ({=hi}) − ({=lo}) = {=hi-lo}."}, {"id": "c_oxoanion_so", "sk": "oxo_hydrides", "ref": "07.1", "n": 3, "lvl": 2, "v": {"_": [{"f": "ЭO^{−} (ClO^{−})", "x": 1, "n": 1}, {"f": "ЭO2^{−} (NO2^{−}, AlO2^{−})", "x": 2, "n": 1}, {"f": "ЭO3^{−} (NO3^{−}, ClO3^{−})", "x": 3, "n": 1}, {"f": "ЭO4^{−} (MnO4^{−}, ClO4^{−})", "x": 4, "n": 1}, {"f": "ЭO2^{2−} (ZnO2^{2−})", "x": 2, "n": 2}, {"f": "ЭO3^{2−} (CO3^{2−}, SO3^{2−})", "x": 3, "n": 2}, {"f": "ЭO4^{2−} (SO4^{2−}, CrO4^{2−}, MnO4^{2−})", "x": 4, "n": 2}, {"f": "ЭO4^{3−} (PO4^{3−})", "x": 4, "n": 3}]}, "q": "Чему равна положительная степень окисления элемента Э в оксоанионе {=f} (введите число без знака +)?", "a": "2 * x - n", "dp": 0, "unit": "", "ex": "Из правила электронейтральности для иона: s + {=x}·(−2) = −{=n}, откуда s = 2·{=x} − {=n} = +{=2*x-n}."}, {"id": "c_so_compound", "sk": "so_calc", "ref": "02.12", "n": 3, "lvl": 2, "v": {"_": [{"f": "K2Cr2O7 (атом Cr)", "ans": 6, "eq": "2·(+1) + 2x + 7·(−2) = 0"}, {"f": "KMnO4 (атом Mn)", "ans": 7, "eq": "+1 + x + 4·(−2) = 0"}, {"f": "K2MnO4 (атом Mn)", "ans": 6, "eq": "2·(+1) + x + 4·(−2) = 0"}, {"f": "K2FeO4 (атом Fe)", "ans": 6, "eq": "2·(+1) + x + 4·(−2) = 0"}, {"f": "Na2S2O3 (средняя с.о. S)", "ans": 2, "eq": "2·(+1) + 2x + 3·(−2) = 0"}, {"f": "KClO3 (атом Cl)", "ans": 5, "eq": "+1 + x + 3·(−2) = 0"}, {"f": "H3PO2 (атом P)", "ans": 1, "eq": "3·(+1) + x + 2·(−2) = 0"}, {"f": "H3PO3 (атом P)", "ans": 3, "eq": "3·(+1) + x + 3·(−2) = 0"}]}, "q": "Определите положительную степень окисления указанного атома в веществе {=f} (введите число без знака +):", "a": "ans", "dp": 0, "unit": "", "ex": "Составляем уравнение электронейтральности: {=eq} → x = +{=ans}."}], "tasks": [{"id": "t01_demo2027", "type": "multi", "sk": "delta_range", "ref": "03.18", "n": 3, "lvl": 2, "q": "[ДЕМО-2027 ФИПИ] Из указанных в ряду элементов выберите ДВА элемента, которые в соединениях могут принимать как положительную, так и отрицательную степень окисления.", "o": ["O", "F", "Al", "Si", "Li"], "a": [0, 3], "ex": "Al (+3) и Li (+1) — металлы, в соединениях только положительны. F — самый электроотрицательный элемент, в соединениях всегда −1. Подходят O (отрицательный в H2O/H2O2 и +2 в OF2) и Si (+4 в SiO2/SiH4 и −4 в Mg2Si)."}, {"id": "t02_no_pos_so", "type": "multi", "sk": "eo_shift", "ref": "01.21", "n": 3, "lvl": 2, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые НЕ проявляют положительной степени окисления.", "o": ["F", "O", "Ne", "Cl", "H"], "a": [0, 2], "ex": "O бывает +2 в OF2, Cl — до +7, H — +1 в воде и кислотах. Положительной с.о. не проявляют фтор F (только −1 и 0) и благородный газ неон Ne (в ЕГЭ только 0)."}, {"id": "t03_no_neg_so", "type": "multi", "sk": "delta_range", "ref": "03.14", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые в школьной модели ЕГЭ НЕ проявляют отрицательной степени окисления.", "o": ["B", "Si", "H", "Al", "O"], "a": [0, 3], "ex": "Si (−4 в Mg2Si), H (−1 в NaH, SiH4) и O (−2, −1) проявляют отрицательные с.о. Не проявляют отрицательной с.о. металл Al (НСО = 0) и бор B (в школьной модели ЕГЭ НСО = 0)."}, {"id": "t04_same_max_so_6", "type": "multi", "sk": "d_exceptions", "ref": "06.7", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые имеют ОДИНАКОВУЮ высшую степень окисления.", "o": ["O", "Fe", "Cr", "Mn", "N"], "a": [1, 2], "ex": "Выписываем ВСО: O (+2 в OF2), Fe (+6 в ферратах), Cr (+6 в хроматах), Mn (+7), N (+5). Одинаковую высшую с.о. (+6) имеют Fe и Cr."}, {"id": "t05_same_max_so_2", "type": "multi", "sk": "d_exceptions", "ref": "06.7", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые имеют ОДИНАКОВУЮ высшую степень окисления.", "o": ["O", "S", "Cu", "F", "Ag"], "a": [0, 2], "ex": "Ловушка на двойное исключение! ВСО: O (+2 в OF2), S (+6), Cu (+2 в CuO/CuSO4), F (0), Ag (+1). Одинаковую ВСО (+2) имеют O и Cu!"}, {"id": "t06_same_min_so_neg1", "type": "multi", "sk": "delta_range", "ref": "03.7", "n": 3, "lvl": 2, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые имеют ОДИНАКОВУЮ низшую степень окисления.", "o": ["H", "S", "Na", "Cl", "P"], "a": [0, 3], "ex": "Выписываем НСО: H (−1 в гидридах), S (−2), Na (0), Cl (−1 в хлоридах), P (−3). Одинаковую низшую с.о. (−1) имеют H и Cl."}, {"id": "t07_same_min_so_zero", "type": "multi", "sk": "delta_range", "ref": "03.14", "n": 3, "lvl": 2, "q": "Из указанных в ряду элементов выберите ДВА элемента, у которых низшая степень окисления равна 0.", "o": ["N", "Fe", "Si", "B", "H"], "a": [1, 3], "ex": "НСО: N (−3), Fe (0, металл), Si (−4 в силицидах), B (0 в школьной модели ЕГЭ), H (−1 в гидридах). Подходят Fe и B."}, {"id": "t08_delta_eq_1", "type": "multi", "sk": "delta_range", "ref": "03.14", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, у которых разность между высшей и низшей степенями окисления (Δ) равна 1.", "o": ["F", "H", "Na", "O", "Mg"], "a": [0, 2], "ex": "Считаем Δ = ВСО − НСО: F (0 − (−1) = 1), H (+1 − (−1) = 2), Na (+1 − 0 = 1), O (+2 − (−2) = 4), Mg (+2 − 0 = 2). Разность 1 дают F и Na!"}, {"id": "t09_delta_eq_2", "type": "multi", "sk": "delta_range", "ref": "03.14", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, у которых разность между высшей и низшей степенями окисления (Δ) равна 2.", "o": ["H", "O", "Al", "Cu", "F"], "a": [0, 3], "ex": "Считаем Δ: H (+1 − (−1) = 2), O (+2 − (−2) = 4), Al (+3 − 0 = 3), Cu (+2 − 0 = 2), F (0 − (−1) = 1). Разность 2 дают H и Cu!"}, {"id": "t10_delta_eq_6", "type": "multi", "sk": "d_exceptions", "ref": "06.17", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, у которых разность между высшей и низшей степенями окисления (Δ) равна 6.", "o": ["S", "Cr", "Fe", "Mn", "O"], "a": [1, 2], "ex": "Ловушка на серу! У S Δ = +6 − (−2) = 8 (а не 6 и не 4!). У Cr (+6 − 0 = 6) и Fe (+6 − 0 = 6) разность равна ровно 6. У Mn Δ = 7, у O Δ = 4."}, {"id": "t11_delta_eq_4", "type": "multi", "sk": "delta_range", "ref": "03.14", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, у которых разность между высшей и низшей степенями окисления (Δ) равна 4.", "o": ["O", "C", "Ti", "S", "Si"], "a": [0, 2], "ex": "У C, S и Si (стандартные неметаллы) Δ = 8! Разность 4 дают кислород O (+2 − (−2) = 4) и металл IVБ группы титан Ti (+4 − 0 = 4)."}, {"id": "t12_abs_hi_eq_lo", "type": "multi", "sk": "delta_range", "ref": "03.15", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, у которых модуль высшей степени окисления равен модулю низшей степени окисления (|ВСО| = |НСО|).", "o": ["O", "N", "H", "F", "S"], "a": [0, 2], "ex": "В школьном курсе ЕГЭ |ВСО| = |НСО| только у 4 элементов: C (±4), Si (±4), O (±2) и H (±1). Из ряда подходят O и H (у N +5 и −3, у F 0 и −1, у S +6 и −2)."}, {"id": "t13_val_not_group", "type": "multi", "sk": "val_period2", "ref": "04.13", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, у которых ВЫСШАЯ ВАЛЕНТНОСТЬ не равна номеру группы.", "o": ["N", "P", "S", "O", "Cl"], "a": [0, 3], "ex": "Переключатель «высшая ВАЛЕНТНОСТЬ»! У P (V), S (VI), Cl (VII) есть 3d-орбитали, их валентность равна номеру группы. У N (IV ≠ V) и O (III ≠ VI) нет 2d-орбиталей."}, {"id": "t14_so_not_group_vs_n", "type": "multi", "sk": "d_exceptions", "ref": "06.17", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, у которых ВЫСШАЯ СТЕПЕНЬ ОКИСЛЕНИЯ не равна номеру группы.", "o": ["N", "Fe", "Cr", "Cu", "Zn"], "a": [1, 3], "ex": "Переключатель «высшая СТЕПЕНЬ ОКИСЛЕНИЯ»! У азота ВСО = +5 (= V — НЕ подходит!). У Cr (+6 = VI) и Zn (+2 = II) совпадает. Не совпадает у Fe (+6 ≠ VIII) и Cu (+2 ≠ I)."}, {"id": "t15_const_so", "type": "multi", "sk": "d_exceptions", "ref": "06.14", "n": 3, "lvl": 2, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые проявляют ПОСТОЯННУЮ степень окисления во всех своих соединениях.", "o": ["H", "Zn", "Cu", "Ag", "O"], "a": [1, 3], "ex": "H (+1/−1), Cu (+1/+2) и O (−2/−1/+2) имеют переменную с.о. Постоянную с.о. в соединениях в курсе ЕГЭ проявляют Zn (+2) и Ag (+1)."}, {"id": "t16_const_val_var_so", "type": "one", "sk": "d_exceptions", "ref": "06.14", "n": 3, "lvl": 3, "q": "Какой элемент обладает ПОСТОЯННОЙ валентностью I, но ПЕРЕМЕННОЙ степенью окисления в сложных веществах?", "o": ["Водород H", "Фтор F", "Натрий Na", "Хлор Cl"], "a": 0, "ex": "У водорода всего одна орбиталь 1s → валентность всегда I, но с.о. бывает +1 (H2O, HCl) и −1 (NaH, SiH4).", "d": {"1": "У фтора постоянны и валентность (I), и степень окисления в соединениях (−1).", "2": "У натрия в соединениях постоянная с.о. +1.", "3": "У хлора переменны и валентность (I, III, V, VII), и степень окисления."}}, {"id": "t17_oxo_eo4_2minus", "type": "multi", "sk": "oxo_hydrides", "ref": "07.14", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые образуют устойчивые оксоанионы общей формулы ЭO4^{2−}.", "o": ["Si", "Mn", "N", "P", "Cr"], "a": [1, 4], "ex": "В ЭO4^{2−} требуется с.о. +6. Si (макс. +4), N (макс. +5) и P (+5, даёт PO4^{3−}, а не 2−) не подходят. Подходят Mn (манганат MnO4^{2−}) и Cr (хромат CrO4^{2−})."}, {"id": "t18_oxo_eo4_minus", "type": "multi", "sk": "oxo_hydrides", "ref": "07.6", "n": 3, "lvl": 2, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые образуют устойчивые оксоанионы общей формулы ЭO4^{−}.", "o": ["S", "Mn", "Cr", "Cl", "N"], "a": [1, 3], "ex": "В ЭO4^{−} требуется с.о. +7 (s − 8 = −1). Из ряда степень окисления +7 и реальные анионы ЭO4^{−} дают Mn (перманганат MnO4^{−}) и Cl (перхлорат ClO4^{−})."}, {"id": "t19_oxo_eo3_minus", "type": "multi", "sk": "oxo_hydrides", "ref": "07.6", "n": 3, "lvl": 2, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые образуют устойчивые оксоанионы общей формулы ЭO3^{−}.", "o": ["C", "N", "S", "Cl", "Si"], "a": [1, 3], "ex": "В ЭO3^{−} требуется с.о. +5 (s − 6 = −1). C, Si (+4, дают CO3^{2−}, SiO3^{2−}) и S (+4/+6, дают SO3^{2−}, SO4^{2−}) не подходят. Подходят N (NO3^{−}) и Cl (ClO3^{−})."}, {"id": "t20_oxo_eo2_minus", "type": "multi", "sk": "oxo_hydrides", "ref": "07.6", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые образуют оксоанионы общей формулы ЭO2^{−}.", "o": ["Al", "Mg", "N", "Na", "C"], "a": [0, 2], "ex": "В ЭO2^{−} требуется с.о. +3 (s − 4 = −1). Na и Mg не образуют оксоанионов, у C нет с.о. +3. Подходят амфотерный Al (метаалюминат AlO2^{−}) и неметалл N (нитрит NO2^{−})."}, {"id": "t21_oxo_eo4_3minus_trap", "type": "multi", "sk": "oxo_hydrides", "ref": "07.6", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые образуют оксоанионы общей формулы ЭO4^{3−}.", "o": ["N", "P", "S", "As", "Cl"], "a": [1, 3], "ex": "Ловушка на азот! В ЭO4^{3−} с.о. равна +5, но азот из-за малого радиуса и потолка валентности IV даёт NO3^{−}, а не NO4^{3−}. Реальные ортоанионы ЭO4^{3−} образуют фосфор P (PO4^{3−}) и мышьяк As (AsO4^{3−})."}, {"id": "t22_lvs_neg_so", "type": "multi", "sk": "oxo_hydrides", "ref": "07.14", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые образуют летучее водородное соединение (ЛВС) и проявляют в нём ОТРИЦАТЕЛЬНУЮ степень окисления.", "o": ["Si", "Na", "C", "N", "Ca"], "a": [2, 3], "ex": "Na (NaH) и Ca (CaH2) — металлы, не образуют ЛВС. Кремний образует ЛВС SiH4, но в нём имеет ПОЛОЖИТЕЛЬНУЮ с.о. +4 (т.к. ЭО(H) > ЭО(Si)). Подходят только C (CH4, C^{−4}) и N (NH3, N^{−3})."}, {"id": "t23_oxide_eo3_trap", "type": "multi", "sk": "oxo_hydrides", "ref": "07.12", "n": 3, "lvl": 3, "q": "Из указанных в ряду элементов выберите ДВА элемента, высший оксид которых в курсе ЕГЭ соответствует общей формуле ЭO3.", "o": ["O", "S", "Fe", "Cr", "Mn"], "a": [1, 3], "ex": "В ЭO3 с.о. равна +6. O сам с собой оксида не даёт, у Mn высший оксид Mn2O7 (+7), а железо Fe в ЕГЭ высшего оксида FeO3 не образует (с.о. +6 только в ферратах). Подходят S (SO3) и Cr (CrO3)."}, {"id": "t24_val_equals_so_no", "type": "multi", "sk": "val_vs_so", "ref": "05.7", "n": 3, "lvl": 3, "q": "Выберите ДВА вещества/иона, в которых валентность указанного элемента НЕ совпадает с модулем его степени окисления:", "o": ["CO (атом углерода)", "CO2 (атом углерода)", "HNO3 (атом азота)", "NH3 (атом азота)", "H2SO4 (атом серы)"], "a": [0, 2], "ex": "В CO2 (IV и +4), NH3 (III и −3), H2SO4 (VI и +6) валентность и |с.о.| совпадают. Расходятся они в CO (C: валентность III, с.о. +2) и HNO3 (N: валентность IV, с.о. +5)."}, {"id": "t25_interm_so_plus3", "type": "multi", "sk": "d_exceptions", "ref": "06.10", "n": 3, "lvl": 2, "q": "Из указанных в ряду элементов выберите ДВА элемента, которые могут проявлять степень окисления +3 в соединениях.", "o": ["Mg", "P", "S", "Cr", "Ca"], "a": [1, 3], "ex": "Mg и Ca имеют постоянную с.о. +2; у серы S (чётная VIA группа) характерны чётные положительные с.о. (+2, +4, +6). Степень окисления +3 проявляют P (P2O3, H3PO3) и Cr (Cr2O3, CrCl3)."}, {"id": "t26_match_val_so", "type": "match", "sk": "val_vs_so", "ref": "05.4", "n": 3, "lvl": 3, "q": "Установите соответствие между веществом (ионом) и характеристикой указанного в скобках атома (валентность / степень окисления):", "left": ["А) HNO3 (азот)", "Б) NH4^{+} (азот)", "В) CO (углерод)", "Г) H2O2 (кислород)"], "right": ["1) Валентность IV, с.о. −3", "2) Валентность II, с.о. −1", "3) Валентность IV, с.о. +5", "4) Валентность III, с.о. +2"], "a": [2, 0, 3, 1], "ex": "А → IV / +5 (потолок 2-го периода); Б → IV / −3 (3 обменные + 1 д.-а. связь); В → III / +2 (тройная связь с д.-а. O → C); Г → II / −1 (неполярная связь —O—O—)."}, {"id": "t27_match_lists", "type": "match", "sk": "kim3_strategy", "ref": "08.5", "n": 3, "lvl": 3, "q": "Установите соответствие между формулировкой задания № 3 КИМ и правильной парой элементов-исключений:", "left": ["А) Высшая с.о. НЕ равна номеру группы (d-элементы)", "Б) |ВСО| = |НСО| (не из IVA группы!)", "В) Разность Δ = ВСО − НСО равна 1", "Г) Высшая валентность НЕ равна номеру группы (2-й период)"], "right": ["1) F (0 − (−1) = 1) и Na (+1 − 0 = 1)", "2) N (IV ≠ V) и O (III ≠ VI)", "3) Fe (+6 ≠ VIII) и Cu (+2 ≠ I)", "4) O (+2/−2) и H (+1/−1)"], "a": [2, 3, 0, 1], "ex": "А → Fe и Cu; Б → O и H (вместе с C и Si составляют четвёрку |ВСО| = |НСО|); В → F и Na (Δ = 1); Г → N и O (нет 2d-орбиталей)."}], "subjectSlug": "chemistry", "_kim": {"3": {"b": 1, "l": "Б"}}, "_kon": {"01": {"t": "Модуль 01. Электроотрицательность: кто перетягивает электроны в связи", "x": "[[Электроотрицательность]] (ЭО) — это способность атома в химическом соединении притягивать к себе общие электронные пары. Чем выше ЭО элемента, тем сильнее он смещает электроны к себе и получает отрицательную [[степень окисления]]."}, "01.1": {"t": "Модуль 01 · Главная мысль.", "x": "[[Электроотрицательность]] (ЭО) — это способность атома в химическом соединении притягивать к себе общие электронные пары. Чем выше ЭО элемента, тем сильнее он смещает электроны к себе и получает отрицательную [[степень окисления]]."}, "01.15": {"t": "Модуль 01 · 3. Рабочий ряд ЭО неметаллов для ЕГЭ", "x": "**Рабочий ряд ЭО:** F (3,98) > O (3,44) > Cl (3,16) > N (3,04) > Br (2,96) > I (2,66) > S (2,58) > C (2,55) > H (2,20) ≈ P (2,19) > B (2,04) > Si (1,90) — далее типичные металлы (Na 0,93; Ca 1,00; Al 1,61)."}, "01.17": {"t": "Модуль 01 · 3. Рабочий ряд ЭО неметаллов для ЕГЭ", "x": "• **O и F** — Кто сильнее тянет e⁻: F сильнее всех; Соединение и с.о.: OF2: O^{+2}, F^{−1}; Почему это важно на ЕГЭ: Главное школьное соединение (наряду с редким O2F2), где кислород положителен; это **фторид кислорода**, а не оксид фтора\n• **Si и H** — Кто сильнее тянет e⁻: H сильнее Si; Соединение и с.о.: SiH4: Si^{+4}, H^{−1}; Почему это важно на ЕГЭ: Силан — исключение среди летучих водородных соединений: у кремния +4, а не −4\n• **B и H** — Кто сильнее тянет e⁻: H сильнее B; Соединение и с.о.: B2H6: B^{+3}, H^{−1}; Почему это важно на ЕГЭ: Бор менее электроотрицателен, чем водород, поэтому в гидридах бор положителен\n• **Металл и H** — Кто сильнее тянет e⁻: H сильнее металлов; Соединение и с.о.: NaH: Na^{+1}, H^{−1}; CaH2: Ca^{+2}, H^{−1}; Почему это важно на ЕГЭ: В гидридах металлов водород всегда имеет степень окисления −1…"}, "01.18": {"t": "Модуль 01 · Тонкость на 100 баллов: фосфин PH3 против силана SiH4", "x": "В справочниках по шкале Полинга ЭО(H) = 2,20, а ЭО(P) = 2,19 — значения практически равны. Тем не менее **в школьной химии и в заданиях ЕГЭ для фосфина PH3 традиционно принимают P^{−3} и H^{+1}** (как у аналога аммиака NH3). А вот для силана SiH4 разница ЭО велика (2,20 против 1,90), поэтому там строго Si^{+4} и H^{−1}!"}, "01.21": {"t": "Модуль 01 · Мост к КИМ (№ 3 КИМ (код 1.3))", "x": "**Как спрашивают:** Задания про выбор элементов, которые «не проявляют положительной степени окисления» или «проявляют отрицательную с.о. в соединении с водородом / кислородом».\n**На чём ловят:** Ловят на фторе (единственный неметалл без положительных с.о.), на кислороде в OF2 и на кремнии в SiH4.\n**Как читать:** Прежде чем ставить знаки + и − в бинарном соединении, всегда сверь пару элементов по рабочему ряду ЭО."}, "02": {"t": "Модуль 02. Степень окисления: смысл, строгая запись и расчёт в любых формулах", "x": "[[Степень окисления]] (с.о.) — это условный заряд атома в соединении, вычисленный в предположении, что все полярные связи в нём полностью ионные (то есть общие электронные пары целиком перешли к более электроотрицательному атому)."}, "02.1": {"t": "Модуль 02 · Главная мысль.", "x": "[[Степень окисления]] (с.о.) — это условный заряд атома в соединении, вычисленный в предположении, что все полярные связи в нём полностью ионные (то есть общие электронные пары целиком перешли к более электроотрицательному атому)."}, "02.6": {"t": "Модуль 02 · Капкан части 2: № 29 (с.о.) против № 30 (заряд иона)", "x": "В заданиях части 2 ЕГЭ требования к формату записи строго разведены:\n- В **задании № 30** (ионные уравнения) пишут **заряды ионов** (SO4^{2−}, Fe^{2+}). Запись заряда иона со знаком впереди (SO4^{-2}, Fe^{+2}) считается грубой ошибкой и обнуляет балл за ионное уравнение.\n- В **задании № 29** (электронный баланс) пишут **степени окисления** со знаком впереди (Cr^{+6}, Mn^{+7}, Fe^{+2}) — подменять их записью заряда несуществующих простых ионов (Cr^{6+}, Mn^{7+}) нельзя."}, "02.12": {"t": "Модуль 02 · 3. Алгебраическое правило электронейтральности", "x": "**Пример 1. Дихромат калия K2Cr2O7:** у калия +1, у кислорода −2, у хрома обозначим x. Составляем уравнение: 2·(+1) + 2·x + 7·(−2) = 0 → 2 + 2x − 14 = 0 → 2x = +12 → x = +6. Проверка: 2·(+1) + 2·(+6) + 7·(−2) = +2 + 12 − 14 = 0.\n**Пример 2. Дихромат-ион Cr2O7^{2−}:** сумма равна заряду иона −2. Уравнение: 2·x + 7·(−2) = −2 → 2x − 14 = −2 → 2x = +12 → x = +6. Проверка: 2·(+6) + 7·(−2) = +12 − 14 = −2.\n**Пример 3. Катион аммония NH4^{+}:** сумма равна +1. У водорода с азотом +1, значит x + 4·(+1) = +1 → x = −3. Проверка: −3 + 4 = +1.\n**Пример 4. Пероксид водорода H2O2 и пероксид натрия Na2O2:** здесь первыми фиксируем H^{+1} и Na^{+1} (у щелочного металла с.о. строго постоянна!). Тогда для кислорода 2·(+1) + 2·x = 0 → x = −1. Между двумя атомами кислорода стоит неполярная связь —O—O—, поэтому каждый атом забирает только по одному электрону."}, "02.15": {"t": "Модуль 02 · 4. Три «хитрых» вещества из ЕГЭ: пирит, железная окалина и тиосульфат", "x": "• **Пирит FeS2** — Если по привычке поставить сере −2, у железа выйдет +4 — такой с.о. в сульфидах не бывает. На деле в пирите стоит ион Fe^{2+} и пероксидоподобный анион S2^{2−} со связью —S—S—. Итог: Fe^{+2}, S^{−1} (проверка: +2 + 2·(−1) = 0).\n• **Железная окалина Fe3O4** — Формальная средняя степень окисления железа дробная (+8/3). В реальном кристалле содержатся два вида катионов: один катион Fe^{2+} и два катиона Fe^{3+}. Баланс степеней окисления: +2 + 2·(+3) + 4·(−2) = 0.\n• **Тиосульфат натрия Na2S2O3** — По формуле 2·(+1) + 2·x + 3·(−2) = 0 получаем среднюю степень окисления серы +2. Структурно атомы серы неравноценны (один центральный, второй заменяет кислород), но в расчётах ЕГЭ используют среднюю с.о. +2: 2·(+1) + 2·(+2) + 3·(−2) = 0.…"}, "03": {"t": "Модуль 03. Высшая, низшая степень окисления и разность Δ", "x": "По номеру группы N в таблице ФИПИ сразу видны границы степеней окисления: для большинства элементов **высшая с.о. = +N**, для неметаллов **низшая с.о. = N − 8**, а для всех металлов (и бора в модели ЕГЭ) **низшая с.о. = 0**. Разность всегда считается алгебраически: Δ = ВСО − НСО."}, "03.1": {"t": "Модуль 03 · Главная мысль.", "x": "По номеру группы N в таблице ФИПИ сразу видны границы степеней окисления: для большинства элементов **высшая с.о. = +N**, для неметаллов **низшая с.о. = N − 8**, а для всех металлов (и бора в модели ЕГЭ) **низшая с.о. = 0**. Разность всегда считается алгебраически: Δ = ВСО − НСО."}, "03.7": {"t": "Модуль 03 · Почему водород не подчиняется формуле N − 8?", "x": "У атома **водорода (H)** на первом уровне помещается максимум 2 электрона (дуплет гелия 1s²), а не 8. Отдав свой единственный электрон, он получает ВСО = +1 (в H2O, HCl), а приняв один электрон до 1s² — получает НСО = −1 (в гидридах NaH, CaH2, SiH4). Поэтому диапазон водорода [−1; +1], а разность Δ(H) = +1 − (−1) = 2."}, "03.10": {"t": "Модуль 03 · 2. Разность Δ = ВСО − НСО: наглядная числовая ось", "x": "**Формула:** Δ = ВСО − НСО = (+N) − (N − 8) = N − N + 8 = 8."}, "03.14": {"t": "Модуль 03 · 3. Сводная таблица диапазонов [НСО; ВСО] и разности Δ", "x": "• **C, Si (IVA)** — −4; +4; +4 − (−4) = 8; У Si низшая −4 проявляется в силицидах (Mg2Si), а не в SiH4!\n• **N, P (VA)** — −3; +5; +5 − (−3) = 8; У N высшая с.о. +5 (равна группе!), хотя валентность лишь IV\n• **S, Se (VIA)** — −2; +6; +6 − (−2) = 8; Не путай Δ с 6 − 2 = 4! Минус на минус даёт плюс\n• **Cl, Br, I (VIIA)** — −1; +7; +7 − (−1) = 8; У Br в школе обычно +5/+7, в расчётах Δ стандартно +7 − (−1) = 8\n• ****Кислород O** (VIA)** — −2; +2 (OF2); +2 − (−2) = 4; Высшая с.о. НЕ +6, а +2!\n• ****Фтор F** (VIIA)** — −1; 0 (F2); 0 − (−1) = 1; У фтора нет положительных с.о.; ВСО = 0 в простом веществе\n• ****Водород H**** — −1; +1; +1 − (−1) = 2; Такая же разность Δ = 2, как у Mg, Ca, Zn, Cu!\n• ****Бор B** (IIIA)** — 0 (в ЕГЭ); +3; +3 − 0 = 3; Формула 3 − 8 = −5 к бору в ЕГЭ **не применяется**!\n• **Металлы IA (Li, Na, K), Ag** — 0; +1; 1; Такая же Δ = 1, как у фтора F!…"}, "03.15": {"t": "Модуль 03 · Четыре элемента с равными по модулю высшей и низшей с.о. (|ВСО| = |НСО|)", "x": "Ещё одна частая формулировка задания № 3: **«модуль высшей с.о. равен модулю низшей с.о.» (|ВСО| = |НСО|)**. Этому условию в школьном курсе ЕГЭ отвечают ровно **четыре** элемента: **C (+4 и −4)**, **Si (+4 и −4)**, **O (+2 и −2)** и **H (+1 и −1)**! Ученики почти всегда вспоминают углерод и кремний, но забывают кислород и водород."}, "03.16": {"t": "Модуль 03 · Антипаттерны расчёта Δ", "x": "Две самые частые ошибки при расчёте Δ:\n1) **Потеря знака минуса:** считают 6 − 2 = 4 вместо 6 − (−2) = 8 для серы.\n2) **Применение N − 8 к металлам и бору:** у натрия НЕ бывает −7, а у алюминия и бора в ЕГЭ НЕ бывает −5 — их низшая с.о. равна 0."}, "03.18": {"t": "Модуль 03 · 4. Разбор вслух: официальное задание № 3 из Демоверсии ЕГЭ-2027", "x": "**Условие (Демоверсия ФИПИ ЕГЭ-2027):** дан ряд элементов 1) O   2) F   3) Al   4) Si   5) Li. Выберите два элемента, которые **в соединениях** могут принимать **как положительную, так и отрицательную** степень окисления."}, "04": {"t": "Модуль 04. Валентность, возбуждение и потолок 2-го периода", "x": "[[Валентность]] — это число ковалентных химических связей, которые атом образует с другими атомами. Валентность всегда записывается **римскими цифрами без знака** (I, II, III, IV…) и ограничена числом доступных валентных орбиталей атома."}, "04.1": {"t": "Модуль 04 · Главная мысль.", "x": "[[Валентность]] — это число ковалентных химических связей, которые атом образует с другими атомами. Валентность всегда записывается **римскими цифрами без знака** (I, II, III, IV…) и ограничена числом доступных валентных орбиталей атома."}, "04.12": {"t": "Модуль 04 · 3. Жёсткий потолок 2-го периода: почему N ≤ IV, O ≤ III, F = I", "x": "• **B (IIIA)** — 2s²2p¹ → 2s¹2p²; III; IV (только в комплексах вроде [BF4]⁻); BF3, B2O3 (III); [BF4]⁻ (IV)\n• **C (IVA)** — 2s²2p² → 2s¹2p³; II, IV; IV; CH4, CO2 (IV), CO (III)\n• ****N (VA)**** — 2s²2p³ (не возбуждается); III; **IV** (≠ V!); NH3 (III), NH4^{+}, HNO3, N2O5 (IV)\n• ****O (VIA)**** — 2s²2p⁴ (не возбуждается); II; **III** (≠ VI!); H2O (II), H3O^{+}, CO (III)\n• ****F (VIIA)**** — 2s²2p⁵ (не возбуждается); I; **I** (≠ VII!); HF, OF2 (всегда только I)"}, "04.13": {"t": "Модуль 04 · Не путай два разных вопроса про азот!", "x": "Самая популярная ловушка № 3 КИМ: **«высшая валентность не равна номеру группы»** против **«высшая степень окисления не равна номеру группы»**.\n- У **азота (N)** высшая валентность равна **IV** (НЕ равна номеру группы V!), а вот высшая степень окисления равна **+5** (РАВНА номеру группы!).\n- У **кислорода (O)** и **фтора (F)** не совпадает с номером группы ни валентность (III и I), ни степень окисления (+2 и 0)."}, "05": {"t": "Модуль 05. Когда валентность не равна степени окисления", "x": "[[Валентность]] считает **число ковалентных связей** (чёрточек), а [[степень окисления]] считает **итоговый сдвиг электронов** (со знаком). Они совпадают по модулю только тогда, когда все связи атома полярны и смещены в одну и ту же сторону."}, "05.1": {"t": "Модуль 05 · Главная мысль.", "x": "[[Валентность]] считает **число ковалентных связей** (чёрточек), а [[степень окисления]] считает **итоговый сдвиг электронов** (со знаком). Они совпадают по модулю только тогда, когда все связи атома полярны и смещены в одну и ту же сторону."}, "05.4": {"t": "Модуль 05 · 1. Четыре системные причины расхождения", "x": "• ****1. Простые вещества**** — Как это работает: Все связи — между одинаковыми атомами; сдвиг электронов равен 0, но чёрточки есть; Ключевые примеры для ЕГЭ (валентность / с.о.): H2 (I / 0), O2 (II / 0), N2 (III / 0), Cl2 (I / 0)\n• ****2. Неполярные связи Э—Э в сложных веществах**** — Как это работает: Связь между двумя одинаковыми атомами добавляет +1 к валентности, но даёт 0 к степени окисления; Ключевые примеры для ЕГЭ (валентность / с.о.): H2O2 (O: II / −1), FeS2 (S: II / −1), C2H6 (C: IV / −3), C2H4 (C: IV / −2), C2H2 (C: IV / −1)\n• ****3. Донорно-акцепторные связи**** — Как это работает: Донор отдаёт *свою* пару электронов в связь: при подсчёте с.о. эта пара либо остаётся у него, либо целиком уходит акцептору; Ключевые примеры для ЕГЭ (валентность / с.о.): CO (C: III / +2; O: III / −2), NH4^{+} (N: IV / −3), H3O^{+} (O: III / −2), HNO3 и N2O5 (N: IV / +5)…"}, "05.7": {"t": "Модуль 05 · 2. Подробный разбор главных «звёзд» ЕГЭ", "x": "**Шаг 1.** **Угарный газ CO:** у углерода два неспаренных 2p-электрона и одна пустая 2p-орбиталь; у кислорода два неспаренных 2p-электрона и неподелённые пары. Две связи образуются по обменному механизму, а третью связь кислород (донор) образует за счёт своей пары на пустую орбиталь углерода (акцептор). Итого **тройная связь**: валентность и углерода, и кислорода равна **III**. Но при расчёте с.о. кислород электроотрицательнее углерода, поэтому его собственная донорная пара просто возвращается к нему, а две обменные пары от углерода переходят к кислороду → C^{+2} и O^{−2}.…"}, "05.8": {"t": "Модуль 05 · Ловушка на 95–100 баллов: H2O2, FeS2, CaC2, H3PO2/H3PO3 и HCHO", "x": "В задании № 3 (и № 4) часто ловят на «хитрых» формулах, где |с.о.| ≠ валентности:\n- В **пероксиде H2O2** у кислорода валентность **II** (при с.о. −1); в **пирите FeS2** у серы валентность **II** (при с.о. −1); в **карбиде кальция CaC2** (связь —C≡C—) у углерода валентность **IV** (при с.о. −1).\n- В **фосфорноватистой кислоте H3PO2** и **фосфористой кислоте H3PO3** фосфор имеет **валентность V** (из-за прямых связей P—H и P=O), но его степень окисления равна соответственно **+1** и **+3**!\n- В **формальдегиде HCHO** и глюкозе C6H12O6 у углерода валентность **IV** при с.о. **0**!"}, "06": {"t": "Модуль 06. d-элементы и полный список исключений таблицы ФИПИ", "x": "У d-элементов в образовании связей участвуют не только внешние 4s-электроны, но и предвнешние 3d-электроны. Поэтому многие d-металлы проявляют широкий набор положительных степеней окисления, а правило «ВСО = номер группы» нарушается у **Fe (+6 вместо +8)** и **Cu (+2 вместо +1)**."}, "06.1": {"t": "Модуль 06 · Главная мысль.", "x": "У d-элементов в образовании связей участвуют не только внешние 4s-электроны, но и предвнешние 3d-электроны. Поэтому многие d-металлы проявляют широкий набор положительных степеней окисления, а правило «ВСО = номер группы» нарушается у **Fe (+6 вместо +8)** и **Cu (+2 вместо +1)**."}, "06.7": {"t": "Модуль 06 · 2. Карта d-элементов для ЕГЭ (выучи эту таблицу наизусть)", "x": "• **Sc (IIIБ)** — 3d¹4s²; +3 (постоянная); 0 / +3; 3; Да (+3 = III)\n• **Ti (IVБ)** — 3d²4s²; +2, +3, +4; 0 / +4; 4; Да (+4 = IV)\n• **V (VБ)** — 3d³4s²; +2, +3, +4, +5; 0 / +5; 5; Да (+5 = V)\n• ****Cr (VIБ)**** — 3d⁵4s¹ (провал); +2, +3, +6 (CrO, Cr2O3, K2CrO4); 0 / +6; 6; Да (+6 = VI)\n• ****Mn (VIIБ)**** — 3d⁵4s²; +2, +3, +4, +6, +7 (MnSO4, MnO2, K2MnO4, KMnO4); 0 / +7; 7; Да (+7 = VII)\n• ****Fe (VIIIБ)**** — 3d⁶4s²; +2, +3, +6 (FeO, Fe2O3, K2FeO4); 0 / **+6**; 6; **НЕТ** (+6 ≠ VIII)\n• ****Cu (IБ)**** — 3d¹⁰4s¹ (провал); +1, +2 (Cu2O, CuO, CuSO4); 0 / **+2**; 2; **НЕТ** (+2 ≠ I)\n• ****Zn (IIБ)**** — 3d¹⁰4s²; **+2 (постоянная!)**; 0 / +2; 2; Да (+2 = II)\n• ****Ag (IБ)**** — 4d¹⁰5s¹ (провал); **+1 (постоянная в ЕГЭ!)**; 0 / +1; 1; Да (+1 = I)"}, "06.10": {"t": "Модуль 06 · 3. Карта характерных (в т.ч. промежуточных) с.о. главных неметаллов", "x": "• **C (IVA)** — Характерные с.о. в ЕГЭ: −4 … +4 (вкл. 0, +2, +4); Ключевые примеры для промежуточных с.о.: CO (+2), HCHO (0), CaC2 (−1), Al4C3 (−4)\n• **Si (IVA)** — Характерные с.о. в ЕГЭ: −4, +4 (реже +2); Ключевые примеры для промежуточных с.о.: Mg2Si (−4), SiO2, SiH4 (+4)\n• **N (VA)** — Характерные с.о. в ЕГЭ: −3, −2, −1, 0, +1, +2, +3, +4, +5; Ключевые примеры для промежуточных с.о.: N2H4 (−2), N2O (+1), NO (+2), HNO2/N2O3 (+3), NO2 (+4)\n• **P (VA)** — Характерные с.о. в ЕГЭ: −3, 0, +1, +3, +5; Ключевые примеры для промежуточных с.о.: Ca3P2/PH3 (−3), H3PO2 (+1), P2O3/H3PO3 (+3), H3PO4 (+5)\n• **S (VIA)** — Характерные с.о. в ЕГЭ: −2, −1, 0, +2, +4, +6; Ключевые примеры для промежуточных с.о.: FeS2 (−1), Na2S2O3 (ср. +2), SO2/H2SO3 (+4), H2SO4 (+6)\n• **Cl, Br, I (VIIA)** — Характерные с.о. в ЕГЭ: −1, 0, +1, +3, +5, +7; Ключевые примеры для промежуточных с.о.: HClO (+1), HClO2 (+3), KClO3 (+5), HClO4 (+7)"}, "06.14": {"t": "Модуль 06 · Ловушка «постоянная валентность» vs «постоянная с.о.»", "x": "Не путай два разных вопроса: **«постоянная степень окисления»** и **«постоянная валентность»**!\n- **Постоянная с.о. в соединениях:** Li–Cs, Be–Ba, Al, Zn, Ag, Sc, F (медь Cu, хром Cr, марганец Mn, железо Fe, кислород O и водород H имеют **переменную** с.о.!).\n- **Ловушка на водород H:** у водорода **постоянная валентность I** (всего одна орбиталь 1s), но **переменная степень окисления** (+1 в воде и кислотах, −1 в гидридах NaH, SiH4)!"}, "06.17": {"t": "Модуль 06 · 5. Разбор вслух: проверяем ряд с d-элементами", "x": "**Шаг 1.** **Выписываем паспорт каждого элемента:** Cr (VIБ, ВСО +6, НСО 0, Δ = 6), Fe (VIIIБ, ВСО +6, НСО 0, Δ = 6), Cu (IБ, ВСО +2, НСО 0, Δ = 2), Zn (IIБ, ВСО +2, НСО 0, Δ = 2), N (VA, ВСО +5, НСО −3, Δ = 8, макс. валентность IV).\n**Шаг 2.** **Ответ на Вопрос А (ВСО ≠ номеру группы):** проверяем каждого. Cr (+6 = VI — нет), **Fe (+6 ≠ VIII — да!)**, **Cu (+2 ≠ I — да!)**, Zn (+2 = II — нет), N (+5 = V — нет!). Ответ: **23**.\n**Шаг 3.** **Ответ на Вопрос Б (Δ = 6):** у Cr Δ = 6 − 0 = 6, у Fe Δ = 6 − 0 = 6. У Cu и Zn Δ = 2, у N Δ = 8. Ответ: **12**."}, "07": {"t": "Модуль 07. Оксоанионы ЭOₓ^{n−}, оксиды и водородные соединения", "x": "Задачи на общие формулы ЭOₓ^{n−}, ЭₓOᵧ и ЭHₙ требуют **двухшаговой проверки**: сначала вычисляем степень окисления элемента Э из формулы, а затем проверяем, **действительно ли элемент образует такой ион или соединение** в химии ЕГЭ."}, "07.1": {"t": "Модуль 07 · Главная мысль.", "x": "Задачи на общие формулы ЭOₓ^{n−}, ЭₓOᵧ и ЭHₙ требуют **двухшаговой проверки**: сначала вычисляем степень окисления элемента Э из формулы, а затем проверяем, **действительно ли элемент образует такой ион или соединение** в химии ЕГЭ."}, "07.4": {"t": "Модуль 07 · Алгоритм проверки: образует ли элемент Э оксоанион ЭOₓ^{n−}?", "x": "• Шаг 1. Вычисли с.о. элемента Э из уравнения s + x·(−2) = −n. Способен ли элемент Э проявлять такую положительную с.о.?\n• Да → Шаг 2. Является ли этот элемент неметаллом (кроме F) или переходным/амфотерным металлом, дающим кислотный оксид в данной с.о.?\n• Да → Шаг 3. Существует ли в курсе ЕГЭ реальный анион именно с таким числом атомов кислорода x?\n• Да → **Элемент ПОДХОДИТ!** (И степень окисления, и конкретный состав аниона подтверждены реальными кислотами/солями ЕГЭ (например, SO4^{2−}, CrO4^{2−}, MnO4^{2−}).)\n• Нет → **ЛОЖНЫЙ КАНДИДАТ — отбросить!** (Углерод имеет +4, но даёт CO3^{2−}, а не CO4^{4−} (в отличие от ортосиликата SiO4^{4−}); азот имеет +5, но из-за малого радиуса и потолка валентности IV даёт NO3^{−}, а не NO4^{3−} (в отличие от PO4^{3−}).)\n• Нет → **Элемент НЕ подходит** (Щелочные и щёлочноземельные металлы (Na, K, Ca, Mg) в соединениях образуют только катионы, а не оксоанионы.)…"}, "07.6": {"t": "Модуль 07 · 2. Шпаргалка реальных оксоанионов ЕГЭ (по общей формуле)", "x": "• **ЭO^{−}** — Требуемая с.о. Э: +1; Реальные анионы из ЕГЭ: ClO^{−} (гипохлорит), BrO^{−}, IO^{−}; Частые ложные кандидаты (НЕ брать!): F (фтор не имеет положительных с.о.)\n• **ЭO2^{−}** — Требуемая с.о. Э: +3; Реальные анионы из ЕГЭ: NO2^{−}, ClO2^{−}, AlO2^{−} (метаалюминат), CrO2^{−}, FeO2^{−}, BO2^{−}; Частые ложные кандидаты (НЕ брать!): P (у фосфора H3PO2 даёт H2PO2^{−} с +1, а не PO2^{−})\n• **ЭO3^{−}** — Требуемая с.о. Э: +5; Реальные анионы из ЕГЭ: NO3^{−}, ClO3^{−}, BrO3^{−}, IO3^{−}, PO3^{−} (метафосфат); Частые ложные кандидаты (НЕ брать!): S (макс. +6, нет +5), C (макс. +4)\n• **ЭO4^{−}** — Требуемая с.о. Э: +7; Реальные анионы из ЕГЭ: MnO4^{−} (перманганат), ClO4^{−} (перхлорат), BrO4^{−}, IO4^{−}; Частые ложные кандидаты (НЕ брать!): N, S, Cr, Fe (у них нет с.о. +7)…"}, "07.9": {"t": "Модуль 07 · 3. Летучие водородные соединения (ЛВС) против ионных гидридов", "x": "• **Летучие водородные соединения (ЛВС)** образуют только **неметаллы IVA–VIIA групп** (газы или летучие жидкости с ковалентными связями): CH4, SiH4 (IVA, ЭH4); NH3, PH3 (VA, ЭH3); H2O, H2S, H2Se (VIA, H2Э); HF, HCl, HBr, HI (VIIA, HЭ).\n• **Солеобразные (ионные) гидриды** образуют активные металлы IA–IIA групп (NaH, KH, CaH2, BaH2) — это твёрдые нелетучие вещества, они **не являются летучими водородными соединениями**! Бор (B2H6) и алюминий (AlH3) также не относятся к классическому ряду ЛВС IVA–VIIA.\n• **Ловушка знака в SiH4:** хотя силан SiH4 входит в ряд ЛВС IVA группы (ЭH4), электроотрицательность водорода (2,20) выше, чем у кремния (1,90). Поэтому в CH4 углерод имеет **−4**, а в SiH4 кремний имеет **+4** (и водород −1)!…"}, "07.12": {"t": "Модуль 07 · 4. Высшие оксиды ЭₓOᵧ и фтор", "x": "• **Фтор (F) не образует оксидов!** Соединение OF2 — это фторид кислорода (O^{+2}, F^{−1}), а не оксид фтора.\n• **Кислород (O)** сам с собой даёт простые вещества O2 и O3, а не оксид. **Железо (Fe)** в ЕГЭ высший оксид FeO3 не образует (для железа характерны оксиды FeO, Fe2O3, Fe3O4, а с.о. +6 реализуется в солях-ферратах K2FeO4)."}, "07.14": {"t": "Модуль 07 · 5. Разбор вслух: две реальные задачи на ЭOₓ^{n−} и ЭHₙ", "x": "**Задача 1:** дан ряд 1) Si   2) Mn   3) N   4) P   5) Cr. Выберите два элемента, которые образуют оксоанион общей формулы ЭO4^{2−}. Вычисляем с.о. элемента: s + 4·(−2) = −2 → s = +6. Проверяем каждого: Si (макс. +4, даёт SiO3^{2−} — нет), **Mn (MnO4^{2−}, манганат — да!)**, N (макс. +5 — нет), P (макс. +5, даёт PO4^{3−} — нет), **Cr (CrO4^{2−}, хромат — да!)**. Ответ: **25**. Особое внимание к Mn: ученики помнят перманганат MnO4^{−} (+7) и часто забывают зелёный манганат MnO4^{2−} (+6)!…"}, "08": {"t": "Модуль 08. Стратегия решения № 3 КИМ: все 12 формулировок за 60 секунд", "x": "Задание № 3 даёт **1 первичный балл**, в ответе всегда ровно **две цифры**, и **порядок цифр значения не имеет** (14 и 41 оба верны). Безошибочное решение строится на едином 4-шаговом алгоритме и проверке слов-переключателей."}, "08.1": {"t": "Модуль 08 · Главная мысль.", "x": "Задание № 3 даёт **1 первичный балл**, в ответе всегда ровно **две цифры**, и **порядок цифр значения не имеет** (14 и 41 оба верны). Безошибочное решение строится на едином 4-шаговом алгоритме и проверке слов-переключателей."}, "08.3": {"t": "Модуль 08 · 1. Единый 4-шаговый алгоритм решения любого задания № 3", "x": "1. Прочти переключатель (Подчеркни: «валентность» или «с.о.», «высшая/низшая/разность», «в соединениях», «не равна», «оксоанион») → 2. Выпиши паспорт 5 элементов (Над каждым элементом ряда подпиши группу, [НСО; ВСО] и при необходимости Δ или макс. валентность) → 3. Отбери ровно 2 элемента (Проверь исключения (F, O, N, H, B, Si, Fe, Cu, Zn) и реальное существование формул) → 4. Контрольная проверка (Убедись, что оставшиеся 3 элемента точно НЕ подходят — это гарантирует защиту от неверного прочтения)"}, "08.5": {"t": "Модуль 08 · 2. Карта всех 12 формулировок задания № 3 ФИПИ", "x": "• **1** — Формулировка в КИМ ЕГЭ: Принимают в соединениях **как +, так и − с.о.** (Демо-2027); На что смотреть сразу: Неметаллы, включая O, H, Si; Главная ловушка: Отбрось F (только −1), металлы и B (в ЕГЭ без −)\n• **2** — Формулировка в КИМ ЕГЭ: **Одинаковая высшая с.о.**; На что смотреть сразу: Номер группы + список исключений; Главная ловушка: F (0), O (+2), Fe (+6), Cu (+2) ≠ номеру группы\n• **3** — Формулировка в КИМ ЕГЭ: **Одинаковая низшая с.о.**; На что смотреть сразу: Металлы + B → 0; неметаллы → N − 8; Главная ловушка: У H и галогенов НСО = −1; у Fe и Na НСО = 0\n• **4** — Формулировка в КИМ ЕГЭ: **Одинаковая разность Δ** (или **|ВСО| = |НСО|**); На что смотреть сразу: Δ = ВСО − НСО со знаком! Для |ВСО| = |НСО| всего 4 элемента: C, Si, O, H; Главная ловушка: Все стандартные неметаллы → 8; O → 4; F/Na → 1; H/Mg/Cu/Zn → 2; B/Al → 3; Cr/Fe → 6…"}}, "_kt": "Задание 3 · Валентность, ЭО и степень окисления", "_mods": {"01": "Электроотрицательность: кто перетягивает электроны в связи", "02": "Степень окисления: смысл, строгая запись и расчёт в любых формулах", "03": "Высшая, низшая степень окисления и разность Δ", "04": "Валентность, возбуждение и потолок 2-го периода", "05": "Когда валентность не равна степени окисления", "06": "d-элементы и полный список исключений таблицы ФИПИ", "07": "Оксоанионы ЭOₓ^{n−}, оксиды и водородные соединения", "08": "Стратегия решения № 3 КИМ: все 12 формулировок за 60 секунд"}, "_skm": {"eo_shift": ["01"], "so_calc": ["02"], "delta_range": ["03"], "val_period2": ["04"], "val_vs_so": ["05"], "d_exceptions": ["06"], "oxo_hydrides": ["07"], "kim3_strategy": ["08"]}, "_fig": []};
